head.b:skin:
:root{
  --bg:#070d0b;
  --sidebar:#0a1210;
  --surface:#0e1714;
  --surface-2:#111f1a;
  --surface-3:#162721;
  --line:#21372e;
  --line-soft:rgba(255,255,255,.065);
  --text:#edf7f2;
  --muted:#8ea59a;
  --muted-2:#657a70;
  --green:#25db75;
  --green-2:#14ad57;
  --gold:#d8b45f;
  --orange:#e8a35e;
  --red:#ff7878;
  --blue:#6eb7ff;
  --radius:16px;
  --radius-sm:12px;
  --shadow:0 18px 55px rgba(0,0,0,.28);
  --sidebar-w:248px;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif
}
*{box-sizing:border-box}
html{background:var(--bg);scroll-behavior:smooth}
body{margin:0;min-height:100vh;background:
  radial-gradient(circle at 75% -10%,rgba(37,219,117,.05),transparent 28%),
  var(--bg);color:var(--text)}
button,input,select,textarea{font:inherit}
button{cursor:pointer}
button:disabled{cursor:not-allowed;opacity:.45}
a{color:inherit;text-decoration:none}
.hidden{display:none!important}
.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}

/* AUTH */
.auth-shell{min-height:100vh;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(420px,.95fr);background:var(--bg)}
.auth-art{position:relative;overflow:hidden;padding:48px;display:flex;align-items:flex-end;background:
  linear-gradient(145deg,rgba(7,13,11,.1),rgba(7,13,11,.95)),
  radial-gradient(circle at 40% 30%,rgba(37,219,117,.16),transparent 36%),
  #0b1511}
.auth-art:before{content:"";position:absolute;inset:0;background-image:
  linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
  linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);
  background-size:38px 38px;mask-image:linear-gradient(to bottom,#000,transparent)}
.auth-art-content{position:relative;z-index:2;max-width:620px}
.auth-mark,.brand-mark{display:grid;place-items:center;background:linear-gradient(145deg,var(--green),#0d8a40);color:#03130a;font-weight:1000;box-shadow:0 10px 30px rgba(37,219,117,.12)}
.auth-mark{width:54px;height:54px;border-radius:17px;font-size:22px}
.auth-art h1{font-size:clamp(34px,5vw,64px);line-height:.97;letter-spacing:-2.5px;margin:22px 0 18px;max-width:660px}
.auth-art p{max-width:620px;color:#a2b8ad;font-size:15px;line-height:1.75;margin:0}
.auth-points{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:28px}
.auth-point{padding:13px 14px;border:1px solid rgba(255,255,255,.075);border-radius:14px;background:rgba(12,25,19,.5);backdrop-filter:blur(12px)}
.auth-point strong{display:block;font-size:12px}
.auth-point span{display:block;margin-top:4px;color:#738a7e;font-size:10px}
.auth-form-wrap{display:grid;place-items:center;padding:28px}
.login-card{width:min(430px,100%);padding:28px;border:1px solid var(--line);border-radius:24px;background:rgba(14,23,20,.92);box-shadow:var(--shadow)}
.login-card .eyebrow{font-size:10px;color:var(--green);font-weight:900;letter-spacing:1.5px;text-transform:uppercase}
.login-card h2{margin:9px 0 7px;font-size:26px;letter-spacing:-.6px}
.login-card>p{margin:0 0 20px;color:var(--muted);font-size:12px;line-height:1.65}
.field{margin:12px 0}
.field label{display:flex;justify-content:space-between;gap:8px;margin-bottom:7px;color:#bdd0c6;font-size:11px;font-weight:750}
.field input,.field select,.field textarea{
  width:100%;border:1px solid var(--line);outline:none;background:#08110e;color:var(--text);
  border-radius:12px;padding:12px 13px;transition:.16s
}
.field input:focus,.field select:focus,.field textarea:focus{border-color:rgba(37,219,117,.48);box-shadow:0 0 0 3px rgba(37,219,117,.07)}
.field textarea{min-height:94px;resize:vertical;line-height:1.5}
.field small{display:block;color:var(--muted-2);font-size:9px;line-height:1.5;margin-top:5px}
.password-wrap{position:relative}.password-wrap input{padding-right:48px}
.password-toggle{position:absolute;right:7px;top:7px;width:35px;height:35px;border:0;border-radius:9px;background:var(--surface-2);color:var(--muted)}
.notice{margin:10px 0 13px;border:1px solid rgba(255,120,120,.27);background:rgba(255,120,120,.07);color:#ffc8c8;border-radius:12px;padding:10px 11px;font-size:10px;line-height:1.55}
.notice.ok{border-color:rgba(37,219,117,.27);background:rgba(37,219,117,.07);color:#baf1cd}

/* BUTTONS */
.btn{border:1px solid transparent;border-radius:11px;padding:10px 13px;font-weight:850;font-size:11px;min-height:40px;display:inline-flex;align-items:center;justify-content:center;gap:7px}
.btn.primary{background:var(--green);color:#03150b}
.btn.primary:hover{background:#3fe187}
.btn.secondary{background:var(--surface-3);color:var(--text);border-color:var(--line)}
.btn.ghost{background:transparent;color:#b8cbc1;border-color:var(--line)}
.btn.danger{background:rgba(255,120,120,.08);color:#ffb0b0;border-color:rgba(255,120,120,.22)}
.btn.wide{width:100%}
.btn.sm{min-height:34px;padding:7px 10px;font-size:10px}
.icon-btn{width:38px;height:38px;border-radius:11px;border:1px solid var(--line);background:var(--surface);color:var(--text);display:grid;place-items:center}
.icon-btn svg,.nav-icon svg,.quick-icon svg,.status-icon svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}

/* APP */
.app{display:grid;grid-template-columns:var(--sidebar-w) minmax(0,1fr);min-height:100vh}
.sidebar{position:sticky;top:0;height:100vh;background:rgba(10,18,16,.97);border-right:1px solid var(--line);display:flex;flex-direction:column;z-index:50}
.sidebar-head{padding:18px 16px 13px;display:flex;align-items:center;gap:10px}
.brand-mark{width:38px;height:38px;border-radius:12px;font-size:15px}
.brand-title{font-size:13px;font-weight:1000;letter-spacing:.4px;line-height:1.1}
.brand-title small{display:block;margin-top:4px;color:#667a70;font-size:8px;letter-spacing:1.25px}
.nav-scroll{padding:4px 10px 16px;overflow:auto;scrollbar-width:thin;scrollbar-color:#244034 transparent;flex:1}
.nav-group{margin:15px 10px 6px;color:#52665d;font-size:8px;font-weight:1000;text-transform:uppercase;letter-spacing:1.55px}
.nav-btn{width:100%;border:0;background:transparent;color:#97aca1;border-radius:10px;padding:9px 10px;display:flex;align-items:center;gap:10px;text-align:left;font-size:11px;font-weight:760;transition:.14s}
.nav-btn:hover{background:rgba(255,255,255,.025);color:#dcebe3}
.nav-btn.active{color:#e9fff0;background:linear-gradient(90deg,rgba(37,219,117,.12),rgba(37,219,117,.025));box-shadow:inset 2px 0 var(--green)}
.nav-icon{width:20px;height:20px;display:grid;place-items:center;flex:0 0 20px;color:#789187}
.nav-btn.active .nav-icon{color:var(--green)}
.sidebar-foot{padding:12px 14px 16px;border-top:1px solid var(--line-soft)}
.side-user{display:flex;align-items:center;gap:9px}
.side-avatar{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--surface-3);border:1px solid var(--line);font-size:11px;font-weight:900}
.side-user-meta{min-width:0;flex:1}.side-user-meta strong{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.side-user-meta span{display:block;color:#637a6e;font-size:8px;margin-top:3px}
.main{min-width:0}
.topbar{height:66px;position:sticky;top:0;z-index:35;display:flex;align-items:center;gap:12px;padding:0 18px;background:rgba(7,13,11,.88);backdrop-filter:blur(18px);border-bottom:1px solid var(--line-soft)}
.menu-btn{display:none}
.top-title h1{font-size:15px;margin:0;letter-spacing:-.2px}.top-title p{margin:3px 0 0;color:#667d72;font-size:8px}
.top-spacer{flex:1}
.role-badge,.status-pill{display:inline-flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid rgba(37,219,117,.16);border-radius:999px;background:rgba(37,219,117,.06);color:#9ee8b9;font-size:8px;font-weight:950;letter-spacing:.35px}
.status-dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px rgba(37,219,117,.08)}
.content{padding:18px;max-width:1600px;margin:0 auto}
.screen{display:none}.screen.active{display:block;animation:enter .15s ease}
@keyframes enter{from{opacity:.72;transform:translateY(3px)}to{opacity:1;transform:none}}


/* MASTER CONTROL */
.master-hero{display:flex;align-items:flex-start;gap:16px;padding:18px;border:1px solid rgba(37,219,117,.20);border-radius:18px;background:radial-gradient(circle at 90% 0,rgba(37,219,117,.10),transparent 34%),linear-gradient(145deg,rgba(14,25,20,.98),rgba(8,16,13,.98));margin-bottom:12px}
.master-hero h2{margin:3px 0 0;font-size:23px;letter-spacing:-.6px}.master-hero p{margin:7px 0 0;color:#789086;font-size:9px;line-height:1.6;max-width:720px}.master-hero-actions{margin-left:auto;display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.master-live{display:inline-flex;align-items:center;gap:6px;padding:7px 9px;border-radius:999px;border:1px solid rgba(37,219,117,.2);background:rgba(37,219,117,.06);color:#91e8ae;font-size:8px;font-weight:950;letter-spacing:.5px}.master-live.warn{border-color:rgba(232,163,94,.25);background:rgba(232,163,94,.06);color:#e7ba87}.master-status-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:10px}.master-status{padding:13px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,rgba(14,23,19,.96),rgba(9,17,14,.96))}.master-status span{display:block;color:#70877c;font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.55px}.master-status strong{display:block;margin-top:8px;font-size:15px}.master-status small{display:block;margin-top:4px;color:#60766b;font-size:8px;line-height:1.45}.master-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:10px}.master-control-list{display:grid;gap:8px}.master-control-row{display:grid;grid-template-columns:minmax(0,1fr) 150px;gap:12px;align-items:center;padding:12px;border:1px solid var(--line-soft);border-radius:13px;background:rgba(255,255,255,.012)}.master-control-row strong{display:block;font-size:10px}.master-control-row span{display:block;margin-top:4px;color:#657c71;font-size:8px;line-height:1.45}.master-control-row select{height:36px;border:1px solid var(--line);border-radius:10px;background:#07110d;color:#c9d8d0;padding:0 9px;outline:none;font-size:9px}.master-control-message{margin-top:9px}.master-control-message textarea{width:100%;min-height:80px;resize:vertical;border:1px solid var(--line);border-radius:12px;background:#07110d;color:#d7e5dd;padding:10px;outline:none;font-size:9px;line-height:1.55}.master-meta{display:grid;gap:8px}.master-meta-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}.master-meta-row span{color:#687f74;font-size:8px}.master-meta-row strong{font-size:9px;text-align:right}.master-quick{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.master-quick button{border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012);color:#b7c9bf;padding:11px;text-align:left;font-size:9px;font-weight:850}.master-quick button:hover{border-color:rgba(37,219,117,.22);color:#dff8e8}.master-danger-note{margin-top:10px;padding:11px;border-radius:12px;border:1px solid rgba(232,163,94,.18);background:rgba(232,163,94,.04);color:#c9ad87;font-size:8px;line-height:1.6}

/* V3.8 MASTER CONTROL — MOBILE RESPONSIVE FIX */
@media(max-width:920px){
  .master-hero{flex-direction:column;align-items:stretch;gap:12px}
  .master-hero-actions{margin-left:0;width:100%;display:grid;grid-template-columns:1fr 1fr;gap:8px}
  .master-hero-actions .btn{width:100%;min-height:40px}
  .master-status-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .master-layout{grid-template-columns:minmax(0,1fr)}
  .master-layout>div,.master-layout>.panel{min-width:0;width:100%;max-width:100%}
}
@media(max-width:640px){
  .master-hero{padding:14px;border-radius:16px}
  .master-hero h2{font-size:22px;line-height:1.12}
  .master-hero p{font-size:9px;line-height:1.55}
  .master-hero-actions{grid-template-columns:1fr 1fr}
  .master-status-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .master-status{min-width:0;padding:11px}
  .master-status strong{font-size:14px;line-height:1.15;overflow-wrap:anywhere}
  .master-status small{overflow-wrap:anywhere}
  .master-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:10px}
  .master-layout>div,.master-layout>.panel,.master-layout>div>.panel{min-width:0;width:100%;max-width:100%;box-sizing:border-box}
  .master-control-row{grid-template-columns:minmax(0,1fr);gap:9px;padding:11px}
  .master-control-row select{width:100%;min-width:0}
  .master-control-message textarea{box-sizing:border-box}
  .master-meta-row{align-items:flex-start}
  .master-meta-row strong{max-width:62%;overflow-wrap:anywhere;word-break:break-word}
  .master-quick{grid-template-columns:1fr 1fr}
  .master-quick button{min-width:0;overflow-wrap:anywhere}
}
@media(max-width:390px){
  .master-hero-actions{grid-template-columns:1fr}
  .master-status-grid{grid-template-columns:1fr 1fr}
  .master-status{padding:10px}
  .master-status strong{font-size:13px}
  .master-quick{grid-template-columns:1fr}
}

/* GENERAL LAYOUT */
.page-head{display:flex;align-items:flex-start;gap:14px;margin:3px 0 16px}
.page-head h2{margin:0;font-size:20px;letter-spacing:-.5px}
.page-head p{margin:5px 0 0;color:var(--muted);font-size:10px;line-height:1.55;max-width:740px}
.page-head-actions{margin-left:auto;display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}
.grid-4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.grid-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.metric,.card,.panel{border:1px solid var(--line);background:linear-gradient(145deg,rgba(15,24,20,.96),rgba(12,20,17,.96));border-radius:var(--radius)}
.metric{padding:15px;min-height:112px;position:relative;overflow:hidden}
.metric:after{content:"";position:absolute;width:100px;height:100px;border-radius:50%;right:-55px;top:-60px;background:rgba(37,219,117,.055)}
.metric-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.metric-label{color:#82998e;font-size:9px;font-weight:800}.metric-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:10px;background:var(--surface-3);color:#82a092}
.metric-value{display:block;margin-top:12px;font-size:22px;font-weight:1000;letter-spacing:-.5px}.metric-sub{display:block;margin-top:4px;color:#60766b;font-size:8px}
.panel{padding:15px}.panel+.panel{margin-top:10px}
.panel-head{display:flex;align-items:center;gap:10px;margin-bottom:12px}.panel-head h3{margin:0;font-size:13px}.panel-head p{margin:3px 0 0;color:var(--muted);font-size:9px}.panel-head-actions{margin-left:auto;display:flex;gap:7px;flex-wrap:wrap}
.subtle{color:var(--muted);font-size:10px;line-height:1.55}
.divider{height:1px;background:var(--line-soft);margin:14px 0}
.hint{padding:10px 11px;border-radius:11px;border:1px solid rgba(216,180,95,.18);background:rgba(216,180,95,.05);color:#c7ba91;font-size:9px;line-height:1.6}
.safe-note{padding:10px 11px;border-radius:11px;border:1px solid rgba(37,219,117,.16);background:rgba(37,219,117,.045);color:#9dc8ab;font-size:9px;line-height:1.6}

/* STATUS / QUICK */
.ops-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:10px;margin-top:10px}
.status-list{display:grid;gap:8px}
.status-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012)}
.status-icon{width:31px;height:31px;border-radius:10px;background:var(--surface-3);display:grid;place-items:center;color:#8eaa9b}
.status-main strong{display:block;font-size:10px}.status-main span{display:block;margin-top:3px;color:#677d72;font-size:8px}
.mini-state{font-size:8px;font-weight:900;padding:6px 7px;border-radius:999px;border:1px solid var(--line);color:#879d92}
.mini-state.ok{border-color:rgba(37,219,117,.18);color:#8de7ad;background:rgba(37,219,117,.05)}
.mini-state.warn{border-color:rgba(232,163,94,.2);color:#e7ba87;background:rgba(232,163,94,.05)}
.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.quick{border:1px solid var(--line-soft);background:rgba(255,255,255,.012);border-radius:12px;padding:11px;text-align:left;color:var(--text)}
.quick-icon{width:28px;height:28px;border-radius:9px;background:var(--surface-3);display:grid;place-items:center;color:var(--green);margin-bottom:9px}
.quick strong{font-size:10px}.quick span{display:block;margin-top:3px;color:#61776c;font-size:8px;line-height:1.4}

/* TOOLBAR & TABLE */
.toolbar-row{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-bottom:11px}
.search-box{position:relative;flex:1;min-width:210px}.search-box input{width:100%;height:38px;padding:0 12px 0 36px;border:1px solid var(--line);border-radius:11px;background:#08110e;color:var(--text);outline:none;font-size:10px}.search-box svg{position:absolute;left:11px;top:10px;width:16px;height:16px;stroke:#60786c;fill:none;stroke-width:2}
.filter-select{height:38px;border:1px solid var(--line);border-radius:11px;background:#08110e;color:#afc0b7;padding:0 10px;outline:none;font-size:10px}
.table-wrap{border:1px solid var(--line);border-radius:14px;overflow:auto;background:rgba(8,17,14,.55)}
table{width:100%;border-collapse:collapse;min-width:760px}
th,td{padding:11px 12px;border-bottom:1px solid var(--line-soft);text-align:left;font-size:9px;white-space:nowrap}
th{position:sticky;top:0;background:#0b1511;color:#667c71;font-size:8px;text-transform:uppercase;letter-spacing:.75px;z-index:2}
td{color:#b7c9bf}tr:last-child td{border-bottom:0}
.empty-row td{text-align:center;padding:30px;color:#647a6f;white-space:normal}
.table-actions{display:flex;gap:5px}
.chip{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:5px 7px;border:1px solid var(--line);font-size:8px;font-weight:850;color:#81988d}
.chip.green{border-color:rgba(37,219,117,.18);background:rgba(37,219,117,.05);color:#91e6af}
.chip.red{border-color:rgba(255,120,120,.18);background:rgba(255,120,120,.05);color:#f1aaaa}
.chip.gold{border-color:rgba(216,180,95,.18);background:rgba(216,180,95,.05);color:#ddc988}

/* FORMS */
.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}
.form-grid .full{grid-column:1/-1}
.form-actions{display:flex;gap:7px;justify-content:flex-end;margin-top:12px;flex-wrap:wrap}
.settings-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:10px}
.settings-tabs{padding:8px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.settings-tab{width:100%;border:0;background:transparent;color:#8fa59a;border-radius:9px;text-align:left;padding:9px 10px;font-size:9px;font-weight:800}
.settings-tab.active{background:rgba(37,219,117,.08);color:#bff1cf}
.setting-pane{display:none}.setting-pane.active{display:block}

/* DRAWER / MODAL */
.drawer-backdrop,.modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.56);backdrop-filter:blur(3px);z-index:70;display:none}
.drawer-backdrop.show,.modal-backdrop.show{display:block}
.modal{position:fixed;z-index:80;left:50%;top:50%;transform:translate(-50%,-50%) scale(.98);width:min(650px,calc(100% - 26px));max-height:86vh;overflow:auto;border:1px solid var(--line);border-radius:18px;background:#0d1713;box-shadow:var(--shadow);padding:16px;opacity:0;pointer-events:none;transition:.14s}
.modal.show{opacity:1;pointer-events:auto;transform:translate(-50%,-50%) scale(1)}
.modal-head{display:flex;align-items:flex-start;gap:10px;margin-bottom:10px}.modal-head h3{margin:0;font-size:15px}.modal-head p{margin:4px 0 0;color:var(--muted);font-size:9px;line-height:1.45}.modal-close{margin-left:auto}

/* PAYMENT */
.gateway-card{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.012)}
.gateway-logo{width:40px;height:40px;border-radius:12px;background:var(--surface-3);display:grid;place-items:center;font-weight:1000;color:var(--gold)}
.gateway-meta strong{display:block;font-size:11px}.gateway-meta span{display:block;margin-top:4px;color:#657b70;font-size:8px}.gateway-actions{display:flex;gap:6px}
.kv-list{display:grid;gap:7px}.kv-row{display:grid;grid-template-columns:minmax(120px,.8fr) minmax(0,1fr) auto;gap:7px;align-items:center}.kv-row input{margin:0}

/* PROMOTIONS */
.promo-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(340px,.95fr);gap:10px}
.promo-list{display:grid;gap:8px}
.promo-item{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:11px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.012)}
.promo-item h4{margin:0;font-size:10px}.promo-item p{margin:4px 0 0;color:#71887d;font-size:8px;line-height:1.45}.promo-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}

/* LOADER / TOAST */
.loader{position:fixed;z-index:120;inset:0;display:grid;place-items:center;background:rgba(7,13,11,.28);backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:.14s}
.loader.show{opacity:1;pointer-events:auto}
.spinner{width:40px;height:40px;border:4px solid rgba(255,255,255,.09);border-top-color:var(--green);border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.toast-root{position:fixed;right:16px;bottom:16px;z-index:130;display:grid;gap:7px;width:min(340px,calc(100% - 32px))}
.toast{border:1px solid var(--line);border-radius:12px;background:#101d17;box-shadow:var(--shadow);padding:10px 11px;font-size:9px;line-height:1.5;color:#c9d8d0;animation:toastIn .18s ease}
.toast.ok{border-color:rgba(37,219,117,.22)}.toast.error{border-color:rgba(255,120,120,.25);color:#ffc0c0}
@keyframes toastIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

@media(max-width:1180px){
  .grid-4{grid-template-columns:repeat(2,1fr)}
  .ops-grid,.promo-layout{grid-template-columns:1fr}
}
@media(max-width:920px){
  .auth-shell{grid-template-columns:1fr}.auth-art{display:none}
  .app{grid-template-columns:1fr}
  .sidebar{position:fixed;left:-270px;width:248px;transition:.18s}
  .sidebar.open{left:0}
  .menu-btn{display:grid}
  .content{padding:14px}.topbar{padding:0 12px}
  .settings-layout{grid-template-columns:1fr}.settings-tabs{display:flex;overflow:auto;gap:5px}.settings-tab{white-space:nowrap;width:auto}
}
@media(max-width:640px){
  .grid-4,.grid-3,.grid-2,.quick-grid,.form-grid{grid-template-columns:1fr}
  .form-grid .full{grid-column:auto}
  .page-head{display:block}.page-head-actions{margin:10px 0 0;justify-content:flex-start}
  .top-title p,.role-badge{display:none}
  .metric{min-height:96px}.metric-value{font-size:19px}
  .gateway-card{grid-template-columns:auto 1fr}.gateway-actions{grid-column:1/-1}
  .kv-row{grid-template-columns:1fr}.kv-row .btn{justify-self:start}
  .login-card{padding:20px}.auth-form-wrap{padding:15px}
}

/* ===== V2 PREMIUM OPERATOR CONSOLE ===== */
:root{
  --sidebar-w:236px;
  --surface-glass:rgba(14,23,20,.82);
  --surface-hover:rgba(255,255,255,.026);
  --green-soft:rgba(37,219,117,.08);
  --shadow-soft:0 14px 34px rgba(0,0,0,.20);
}
body{background:
  radial-gradient(circle at 76% -14%,rgba(37,219,117,.075),transparent 30%),
  radial-gradient(circle at 22% 112%,rgba(216,180,95,.035),transparent 27%),
  var(--bg)}
.sidebar{background:linear-gradient(180deg,rgba(9,17,14,.99),rgba(8,15,13,.98));box-shadow:10px 0 32px rgba(0,0,0,.09)}
.sidebar-head{height:68px;border-bottom:1px solid rgba(255,255,255,.035)}
.brand-mark{border:1px solid rgba(89,255,145,.22);box-shadow:0 8px 22px rgba(37,219,117,.10)}
.nav-scroll{padding-top:8px}
.nav-btn{min-height:39px;border:1px solid transparent}
.nav-btn:hover{border-color:rgba(255,255,255,.035);background:rgba(255,255,255,.022)}
.nav-btn.active{border-color:rgba(37,219,117,.08);background:linear-gradient(90deg,rgba(37,219,117,.115),rgba(37,219,117,.02));box-shadow:inset 2px 0 var(--green),0 5px 18px rgba(0,0,0,.08)}
.topbar{height:68px;background:rgba(7,13,11,.82);border-bottom:1px solid rgba(255,255,255,.055)}
.topbar-search{width:min(340px,32vw);position:relative}
.topbar-search input{width:100%;height:38px;border:1px solid var(--line);border-radius:11px;background:rgba(8,17,14,.88);color:var(--text);outline:none;padding:0 12px 0 36px;font-size:10px}
.topbar-search input:focus{border-color:rgba(37,219,117,.35)}
.topbar-search svg{position:absolute;left:11px;top:10px;width:16px;height:16px;fill:none;stroke:#5f766b;stroke-width:2}
.top-date{color:#6e8378;font-size:9px;white-space:nowrap;padding:0 3px}
.content{padding:20px 22px 32px}
.page-head{margin-bottom:15px}
.page-head h2{font-size:21px;letter-spacing:-.58px}
.page-kicker{display:inline-flex;align-items:center;gap:6px;margin-bottom:7px;color:#6e877a;font-size:8px;font-weight:950;text-transform:uppercase;letter-spacing:1.25px}
.page-kicker:before{content:"";width:16px;height:1px;background:var(--green)}
.metric{box-shadow:0 8px 28px rgba(0,0,0,.085);transition:transform .16s,border-color .16s;background:
  linear-gradient(145deg,rgba(15,25,21,.99),rgba(11,19,16,.96))}
.metric:hover{transform:translateY(-1px);border-color:#29473a}
.metric-icon{font-weight:900;color:#85a397}
.metric-trend{display:inline-flex;align-items:center;gap:4px;margin-top:5px;padding:4px 6px;border-radius:999px;background:rgba(37,219,117,.05);border:1px solid rgba(37,219,117,.1);color:#78d99a;font-size:7px;font-weight:900}
.metric-trend.neutral{background:rgba(255,255,255,.02);border-color:var(--line-soft);color:#71887c}
.panel{box-shadow:0 8px 28px rgba(0,0,0,.07)}
.dashboard-layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(310px,.55fr);gap:10px;margin-top:10px}
.dashboard-bottom{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,.75fr);gap:10px;margin-top:10px}
.chart-shell{height:250px;position:relative;padding:8px 4px 0}
.chart-grid{position:absolute;inset:15px 8px 38px 8px;display:grid;grid-template-rows:repeat(4,1fr);pointer-events:none}
.chart-grid span{border-top:1px dashed rgba(255,255,255,.055)}
.chart-bars{position:absolute;left:18px;right:14px;top:22px;bottom:38px;display:grid;grid-template-columns:repeat(7,1fr);align-items:end;gap:12px}
.chart-day{display:flex;align-items:flex-end;justify-content:center;gap:4px;height:100%;position:relative}
.chart-bar{width:min(12px,36%);min-height:3px;border-radius:5px 5px 2px 2px;transition:height .25s ease}
.chart-bar.deposit{background:linear-gradient(180deg,#39e783,#14944d);box-shadow:0 7px 18px rgba(37,219,117,.08)}
.chart-bar.withdraw{background:linear-gradient(180deg,#d6bd76,#846b31)}
.chart-labels{position:absolute;left:12px;right:8px;bottom:8px;display:grid;grid-template-columns:repeat(7,1fr);gap:12px;text-align:center;color:#5f766b;font-size:7px;font-weight:850}
.chart-legend{display:flex;gap:11px;align-items:center;margin-left:auto;color:#70877b;font-size:8px}
.chart-legend span{display:flex;align-items:center;gap:5px}
.legend-dot{width:7px;height:7px;border-radius:2px;background:var(--green)}
.legend-dot.gold{background:var(--gold)}
.pending-list,.activity-list{display:grid;gap:7px}
.pending-item,.activity-item{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:9px;align-items:center;padding:10px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.011)}
.pending-count{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:rgba(216,180,95,.07);border:1px solid rgba(216,180,95,.13);color:#e1ca87;font-size:10px;font-weight:950}
.pending-main strong,.activity-main strong{display:block;font-size:9px}
.pending-main span,.activity-main span{display:block;margin-top:3px;color:#61776c;font-size:8px;line-height:1.35}
.activity-dot{width:8px;height:8px;border-radius:50%;background:#667c70;box-shadow:0 0 0 4px rgba(255,255,255,.025)}
.activity-dot.ok{background:var(--green)}
.activity-time{color:#53675d;font-size:7px}
.section-tabs{display:flex;gap:5px;border:1px solid var(--line);background:#09120f;border-radius:12px;padding:4px;width:max-content;max-width:100%;overflow:auto}
.section-tab{border:0;border-radius:8px;background:transparent;color:#72887d;padding:7px 10px;font-size:8px;font-weight:900;white-space:nowrap}
.section-tab.active{background:var(--surface-3);color:#dcebe3}
.table-wrap{background:linear-gradient(180deg,rgba(8,17,14,.8),rgba(8,15,13,.65));box-shadow:inset 0 1px rgba(255,255,255,.018)}
tbody tr{transition:background .12s}
tbody tr:not(.empty-row):hover{background:rgba(37,219,117,.018)}
.detail-btn{border:1px solid var(--line);border-radius:8px;background:var(--surface-2);color:#a8beb3;padding:6px 8px;font-size:8px;font-weight:850}
.detail-btn:hover{border-color:rgba(37,219,117,.22);color:#d9eee2}
.toolbar-row{background:rgba(255,255,255,.009);border-radius:12px}
.panel-head h3{letter-spacing:-.12px}

/* detail drawer */
.detail-overlay{position:fixed;inset:0;z-index:88;background:rgba(0,0,0,.42);backdrop-filter:blur(2px);opacity:0;pointer-events:none;transition:.18s}
.detail-overlay.show{opacity:1;pointer-events:auto}
.detail-drawer{position:fixed;z-index:90;right:-520px;top:0;width:min(480px,100%);height:100vh;background:#0b1511;border-left:1px solid var(--line);box-shadow:-26px 0 60px rgba(0,0,0,.32);display:flex;flex-direction:column;transition:right .2s ease}
.detail-drawer.show{right:0}
.detail-head{padding:17px 17px 14px;border-bottom:1px solid var(--line-soft);display:flex;align-items:flex-start;gap:10px}
.detail-head h3{margin:0;font-size:15px}.detail-head p{margin:4px 0 0;color:#657c70;font-size:8px}
.detail-body{padding:15px 17px;overflow:auto;flex:1}
.detail-section{padding:12px 0;border-bottom:1px solid var(--line-soft)}
.detail-section:first-child{padding-top:0}.detail-section:last-child{border-bottom:0}
.detail-section-title{margin-bottom:8px;color:#70867b;font-size:8px;font-weight:950;text-transform:uppercase;letter-spacing:1px}
.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.detail-kv{padding:9px 10px;border:1px solid var(--line-soft);border-radius:10px;background:rgba(255,255,255,.012)}
.detail-kv span{display:block;color:#5e7469;font-size:7px;text-transform:uppercase;letter-spacing:.6px}
.detail-kv strong{display:block;margin-top:4px;color:#c8d8d0;font-size:9px;word-break:break-word}
.detail-foot{padding:12px 17px 16px;border-top:1px solid var(--line-soft);display:flex;gap:7px;justify-content:flex-end}

/* polished auth */
.auth-art{background:
  linear-gradient(145deg,rgba(7,13,11,.06),rgba(7,13,11,.97)),
  radial-gradient(circle at 36% 26%,rgba(37,219,117,.19),transparent 33%),
  radial-gradient(circle at 78% 72%,rgba(216,180,95,.06),transparent 25%),
  #0a1511}
.login-card{background:linear-gradient(160deg,rgba(15,26,21,.97),rgba(11,19,16,.96));border-color:#274338}
@media(max-width:1180px){
  .dashboard-layout,.dashboard-bottom{grid-template-columns:1fr}
}
@media(max-width:920px){
  .topbar-search{display:none}
  .top-date{display:none}
}
@media(max-width:640px){
  .content{padding:13px 11px 24px}
  .page-head h2{font-size:18px}
  .detail-grid{grid-template-columns:1fr}
  .chart-bars,.chart-labels{gap:6px}
  .chart-shell{height:220px}
  .metric{padding:13px}
  table{min-width:680px}
}


/* V2.4 functional UI polish */

.login-submit{display:flex;align-items:center;justify-content:center;gap:9px}
.login-submit svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.login-submit:disabled{opacity:.7;cursor:wait}

.top-title p,.page-head p{display:none!important}
.page-head{align-items:center}
.page-head h2{font-size:19px}
.login-card{padding:30px;border-radius:26px;box-shadow:0 18px 44px rgba(0,0,0,.28)}
.login-card .eyebrow{letter-spacing:1.8px}
.login-card h2{margin:10px 0 4px;font-size:29px}
.login-card .login-subtitle{margin:0 0 20px;color:#87a095;font-size:12px;line-height:1.6}
.password-wrap input{padding-right:50px}
.password-toggle{display:grid;place-items:center;cursor:pointer;transition:.16s;background:rgba(255,255,255,.04);color:#a7bdb2}
.password-toggle:hover,.password-toggle.active{background:rgba(37,219,117,.10);color:var(--green);border:1px solid rgba(37,219,117,.18)}
.password-toggle svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.drawer-close{display:none}
.top-actions{display:flex;align-items:center;gap:8px}
.logout-icon svg,.drawer-close svg,.menu-btn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
@media(max-width:920px){
  body.drawer-open{overflow:hidden}
  .sidebar{z-index:91;left:-280px;width:min(86vw,280px);box-shadow:20px 0 50px rgba(0,0,0,.45)}
  .sidebar.open{left:0}
  .drawer-backdrop{z-index:90;background:rgba(0,0,0,.68)}
  .drawer-close{display:grid;margin-left:auto}
  .sidebar-head{gap:12px}
  .content{padding:12px 12px 24px}
  .login-card{padding:22px 18px;border-radius:22px}
  .login-card h2{font-size:24px}
  .topbar{gap:8px}
}


/* ===== V2.5 DASHBOARD + MEMBERS MASTER ===== */
.dash-command{display:flex;align-items:center;gap:14px;justify-content:space-between;padding:18px 19px;margin-bottom:12px;border:1px solid rgba(64,113,90,.25);border-radius:17px;background:radial-gradient(circle at 90% 10%,rgba(37,219,117,.10),transparent 28%),linear-gradient(135deg,rgba(17,29,24,.98),rgba(10,18,15,.98));box-shadow:0 16px 42px rgba(0,0,0,.16);overflow:hidden;position:relative}
.dash-command:after{content:"";position:absolute;right:-65px;bottom:-86px;width:190px;height:190px;border:1px solid rgba(37,219,117,.07);border-radius:50%}
.dash-command-main{position:relative;z-index:1}.dash-command-main h2{font-size:22px;margin:0;letter-spacing:-.55px}
.dash-command-meta{display:flex;align-items:center;gap:7px;margin-top:7px;flex-wrap:wrap}
.live-tag{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 9px;border-radius:999px;background:rgba(37,219,117,.06);border:1px solid rgba(37,219,117,.13);font-size:8px;font-weight:950;color:#79d99a}
.live-tag i{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(37,219,117,.08)}
.command-role{font-size:8px;color:#70877b;font-weight:900;text-transform:uppercase;letter-spacing:.7px}
.command-actions{display:flex;align-items:center;gap:7px;position:relative;z-index:1;flex-wrap:wrap;justify-content:flex-end}
.dashboard-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.dash-kpi{position:relative;min-height:132px;padding:14px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(155deg,rgba(15,26,21,.99),rgba(10,18,15,.98));box-shadow:0 8px 26px rgba(0,0,0,.08);overflow:hidden}
.dash-kpi:after{content:"";position:absolute;width:90px;height:90px;border-radius:50%;right:-32px;bottom:-40px;background:rgba(255,255,255,.014)}
.dash-kpi-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.dash-kpi-label{font-size:8px;font-weight:950;letter-spacing:.95px;color:#70867b;text-transform:uppercase}
.dash-kpi-icon{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:rgba(37,219,117,.055);border:1px solid rgba(37,219,117,.10);color:#74d796}
.dash-kpi-icon.gold{background:rgba(216,180,95,.055);border-color:rgba(216,180,95,.11);color:#d9bf75}
.dash-kpi-icon svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.dash-kpi-value{display:block;margin-top:14px;font-size:23px;letter-spacing:-.65px;color:#edf7f1;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dash-kpi-foot{margin-top:7px;display:flex;align-items:center;justify-content:space-between;gap:8px}.dash-kpi-note{font-size:7px;color:#5f756a;font-weight:800}
.dash-main-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,.5fr);gap:10px;margin-top:10px}
.dash-lower-grid{display:grid;grid-template-columns:minmax(280px,.7fr) minmax(0,1.3fr);gap:10px;margin-top:10px}
.panel-premium{border-color:rgba(62,101,84,.24);background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98))}
.panel-title-row{display:flex;align-items:center;justify-content:space-between;gap:10px}.panel-title-row h3{margin:0;font-size:11px;letter-spacing:-.1px}.panel-title-row .tiny{font-size:7px;color:#61766b;font-weight:800}
.queue-list{display:grid;gap:7px}.queue-row{width:100%;display:grid;grid-template-columns:36px minmax(0,1fr) auto;align-items:center;gap:10px;text-align:left;padding:10px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.011);color:inherit}
.queue-row:hover{border-color:rgba(37,219,117,.16);background:rgba(37,219,117,.018)}.queue-badge{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;font-size:11px;font-weight:950;background:rgba(216,180,95,.06);border:1px solid rgba(216,180,95,.12);color:#dfc67f}
.queue-copy strong{display:block;font-size:9px;color:#d7e6de}.queue-copy span{display:block;margin-top:3px;font-size:7px;color:#60766b}.queue-arrow{width:26px;height:26px;border-radius:8px;display:grid;place-items:center;border:1px solid var(--line-soft);color:#6f877b}
.queue-arrow svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.member-pulse{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.pulse-cell{padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}
.pulse-cell span{display:block;color:#61776c;font-size:7px;font-weight:900;text-transform:uppercase;letter-spacing:.6px}.pulse-cell strong{display:block;margin-top:5px;font-size:14px;color:#dce9e2}
.system-compact{display:grid;grid-template-columns:1fr 1fr;gap:7px}.system-tile{padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}
.system-tile-top{display:flex;align-items:center;justify-content:space-between;gap:6px}.system-tile strong{font-size:8px}.system-tile p{display:block!important;margin:5px 0 0!important;color:#5f756a!important;font-size:7px!important;line-height:1.35!important}
.activity-list.compact .activity-item{padding:9px}.dashboard-empty{padding:20px;text-align:center;color:#62776c;font-size:8px;border:1px dashed var(--line);border-radius:12px}
.members-command{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.members-command h2{margin:0;font-size:21px;letter-spacing:-.5px}.members-command-actions{display:flex;gap:7px;align-items:center}
.member-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:10px}.member-stat{padding:12px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(155deg,rgba(14,24,20,.98),rgba(10,18,15,.98))}
.member-stat span{display:block;color:#657b70;font-size:7px;font-weight:950;letter-spacing:.72px;text-transform:uppercase}.member-stat strong{display:block;margin-top:7px;color:#e0eee6;font-size:17px;letter-spacing:-.35px}.member-stat small{display:block;margin-top:4px;color:#51665b;font-size:7px}
.member-workspace{border:1px solid rgba(62,101,84,.24);border-radius:15px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}
.member-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 150px 160px auto;gap:7px;padding:11px;border-bottom:1px solid var(--line-soft);background:rgba(255,255,255,.008)}
.member-resultbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 11px;border-bottom:1px solid var(--line-soft);font-size:7px;color:#62776c}.member-resultbar strong{color:#96aa9f}
