.growth-hero h2{margin:0;font-size:21px;letter-spacing:-.5px}.growth-hero-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.growth-live{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;border:1px solid rgba(37,219,117,.12);background:rgba(37,219,117,.05);font-size:7px;font-weight:950;color:#7bd99b}
.growth-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:10px}.growth-stat{padding:12px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(150deg,rgba(14,24,20,.98),rgba(9,17,14,.98))}
.growth-stat span{display:block;color:#62786d;font-size:7px;font-weight:950;text-transform:uppercase;letter-spacing:.65px}.growth-stat strong{display:block;margin-top:7px;font-size:17px;color:#e1ede6}.growth-stat small{display:block;margin-top:4px;color:#51665b;font-size:7px}
.promo-workspace{display:grid;grid-template-columns:minmax(360px,.9fr) minmax(0,1.1fr);gap:10px}.promo-library,.promo-editor{border:1px solid rgba(62,101,84,.24);border-radius:15px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}
.promo-toolbar{display:grid;grid-template-columns:minmax(180px,1fr) 130px 130px;gap:7px;padding:10px;border-bottom:1px solid var(--line-soft)}.promo-library-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 10px;border-bottom:1px solid var(--line-soft);font-size:7px;color:#61776c}
.promo-library-meta strong{color:#91a79b}.promo-card-list{display:grid;gap:7px;padding:9px;max-height:760px;overflow:auto}
.promo-card{display:grid;grid-template-columns:72px minmax(0,1fr);gap:10px;padding:9px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012);transition:.15s}
.promo-card:hover{border-color:rgba(37,219,117,.15);background:rgba(37,219,117,.017)}.promo-thumb{height:72px;border-radius:10px;border:1px solid var(--line-soft);background:linear-gradient(145deg,rgba(37,219,117,.08),rgba(216,180,95,.04));overflow:hidden;display:grid;place-items:center;color:#6f887b;font-size:8px;font-weight:950}
.promo-thumb img{width:100%;height:100%;object-fit:cover;display:block}.promo-card-main{min-width:0}.promo-card-top{display:flex;align-items:flex-start;gap:8px}.promo-card-top h4{margin:0;min-width:0;flex:1;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.promo-card-top .chip{flex:0 0 auto}
.promo-card-summary{margin-top:4px;color:#60766b;font-size:7px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.promo-card-meta{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.promo-card-actions{display:flex;gap:5px;margin-top:8px}
.promo-editor-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 13px;border-bottom:1px solid var(--line-soft)}.promo-editor-head h3{margin:0;font-size:11px}.promo-editor-head span{font-size:7px;color:#61776c;font-weight:900}
.promo-preview{margin:11px;border:1px solid rgba(37,219,117,.11);border-radius:13px;overflow:hidden;background:linear-gradient(145deg,rgba(37,219,117,.035),rgba(255,255,255,.01))}
.promo-preview-cover{height:116px;background:linear-gradient(135deg,rgba(37,219,117,.11),rgba(216,180,95,.055));display:grid;place-items:center;color:#738b7f;font-size:8px;font-weight:900;overflow:hidden}.promo-preview-cover img{width:100%;height:100%;object-fit:cover}
.promo-preview-body{padding:11px}.promo-preview-head{display:flex;gap:8px;align-items:flex-start}.promo-preview-head strong{min-width:0;flex:1;font-size:11px}.promo-preview-body p{display:block!important;margin:6px 0 0!important;color:#647a6f!important;font-size:8px!important;line-height:1.45!important}.promo-preview-meta{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}
.promo-editor-tabs{display:flex;gap:4px;padding:0 11px 10px;overflow:auto}.promo-editor-tab{border:1px solid var(--line-soft);background:rgba(255,255,255,.012);color:#70877b;border-radius:8px;padding:7px 9px;font-size:7px;font-weight:950;white-space:nowrap}.promo-editor-tab.active{background:rgba(37,219,117,.065);border-color:rgba(37,219,117,.13);color:#a8daba}
.promo-pane{display:none;padding:0 11px 11px}.promo-pane.active{display:block}.promo-pane .form-grid{gap:0 9px}.promo-form-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 11px;border-top:1px solid var(--line-soft);background:rgba(255,255,255,.006)}
.promo-revision{font-size:7px;color:#60766b;font-weight:900}.promo-form-actions{display:flex;gap:6px}
.reward-hero-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:10px}.reward-module{padding:13px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(150deg,rgba(14,24,20,.98),rgba(9,17,14,.98))}
.reward-module-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.reward-module h3{margin:0;font-size:9px}.reward-module p{display:block!important;margin:7px 0 0!important;color:#5e7469!important;font-size:7px!important;line-height:1.45!important}
.reward-readiness{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:10px}.reward-pipeline{display:grid;gap:7px}.reward-step{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:9px;align-items:center;padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}
.reward-step-num{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;background:rgba(216,180,95,.055);border:1px solid rgba(216,180,95,.11);color:#d9c17a;font-size:8px;font-weight:950}.reward-step strong{display:block;font-size:8px}.reward-step span{display:block;margin-top:3px;color:#5d7368;font-size:7px}
.reward-gate-list{display:grid;gap:7px}.reward-gate{padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}.reward-gate-top{display:flex;align-items:center;justify-content:space-between;gap:7px}.reward-gate strong{font-size:8px}.reward-gate p{display:block!important;margin:5px 0 0!important;color:#5c7166!important;font-size:7px!important;line-height:1.4!important}
.reward-warning{margin-top:10px;padding:11px;border:1px solid rgba(216,180,95,.12);border-radius:11px;background:rgba(216,180,95,.035);font-size:7px;color:#7b7155;line-height:1.5}
@media(max-width:1180px){.growth-stats{grid-template-columns:repeat(3,1fr)}.promo-workspace,.reward-readiness{grid-template-columns:1fr}.reward-hero-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){.growth-hero{align-items:flex-start;flex-direction:column}.growth-hero-actions{width:100%}.growth-stats{grid-template-columns:1fr 1fr}.promo-toolbar{grid-template-columns:1fr 1fr}.promo-toolbar .search-box{grid-column:1/-1}.promo-card-list{max-height:none}.promo-preview-cover{height:100px}.reward-hero-grid{grid-template-columns:1fr 1fr}}
@media(max-width:430px){.growth-stats,.reward-hero-grid{grid-template-columns:1fr 1fr}.promo-toolbar{grid-template-columns:1fr}.promo-toolbar .search-box{grid-column:auto}.promo-card{grid-template-columns:58px minmax(0,1fr)}.promo-thumb{height:58px}.promo-form-footer{align-items:flex-start;flex-direction:column}.promo-form-actions{width:100%}.promo-form-actions .btn{flex:1}}


/* ===== V2.9 SYSTEM SUITE ===== */
.system-hero{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:17px 18px;margin-bottom:10px;border:1px solid rgba(62,101,84,.24);border-radius:16px;background:radial-gradient(circle at 92% 0%,rgba(37,219,117,.075),transparent 26%),linear-gradient(145deg,rgba(15,25,21,.99),rgba(9,17,14,.98));box-shadow:0 14px 36px rgba(0,0,0,.13)}
.system-hero h2{margin:0;font-size:21px;letter-spacing:-.5px}.system-hero-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.system-secure{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;border:1px solid rgba(37,219,117,.12);background:rgba(37,219,117,.05);font-size:7px;font-weight:950;color:#7bd99b}
.system-secure svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2}
.system-stats,.security-grid,.audit-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:10px}
.system-stat,.security-card,.audit-stat{padding:12px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(150deg,rgba(14,24,20,.98),rgba(9,17,14,.98))}
.system-stat span,.security-card span,.audit-stat span{display:block;color:#62786d;font-size:7px;font-weight:950;text-transform:uppercase;letter-spacing:.65px}
.system-stat strong,.audit-stat strong{display:block;margin-top:7px;font-size:17px;color:#e1ede6}.security-card strong{display:block;margin-top:7px;font-size:11px;color:#e1ede6;word-break:break-word}
.system-stat small,.security-card small,.audit-stat small{display:block;margin-top:4px;color:#51665b;font-size:7px}
.payment-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,.75fr);gap:10px}.payment-connections{border:1px solid rgba(62,101,84,.24);border-radius:15px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}
.payment-list{display:grid;gap:7px;padding:9px}.payment-connection{padding:11px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012)}.payment-connection-head{display:flex;align-items:center;gap:9px}.payment-connection-logo{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:rgba(37,219,117,.055);border:1px solid rgba(37,219,117,.1);color:#7bdb9b;font-size:9px;font-weight:950}
.payment-connection-copy{min-width:0;flex:1}.payment-connection-copy strong{display:block;font-size:9px;overflow:hidden;text-overflow:ellipsis}.payment-connection-copy span{display:block;margin-top:3px;color:#5f756a;font-size:7px;overflow:hidden;text-overflow:ellipsis}.payment-connection-head .chip{flex:0 0 auto}
.payment-connection-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:9px}.payment-meta{padding:8px;border:1px solid var(--line-soft);border-radius:9px;background:rgba(0,0,0,.08)}.payment-meta span{display:block;color:#5c7166;font-size:7px;text-transform:uppercase}.payment-meta strong{display:block;margin-top:4px;font-size:8px}.payment-connection-actions{display:flex;justify-content:flex-end;margin-top:9px}
.adapter-list{display:grid;gap:7px}.adapter-card{padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}.adapter-card-top{display:flex;align-items:center;justify-content:space-between;gap:7px}.adapter-card strong{font-size:8px}.adapter-card p{display:block!important;margin:5px 0 0!important;color:#5c7166!important;font-size:7px!important;line-height:1.4!important}
.payment-policy{margin-top:10px;padding:11px;border:1px solid rgba(216,180,95,.12);border-radius:11px;background:rgba(216,180,95,.035);font-size:7px;color:#7b7155;line-height:1.5}
.report-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.report-card{padding:14px;border:1px solid rgba(62,101,84,.24);border-radius:14px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98))}
.report-card-head{display:flex;align-items:center;gap:9px}.report-icon{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:rgba(37,219,117,.055);border:1px solid rgba(37,219,117,.1);color:#78d99a}.report-icon.gold{background:rgba(216,180,95,.055);border-color:rgba(216,180,95,.11);color:#d9c17a}.report-icon svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.report-card-head h3{margin:0;font-size:10px}.report-card-head span{display:block;margin-top:3px;color:#5f756a;font-size:7px}.report-card-body{margin-top:11px;padding-top:10px;border-top:1px solid var(--line-soft)}.report-specs{display:grid;grid-template-columns:1fr 1fr;gap:6px}.report-spec{padding:8px;border:1px solid var(--line-soft);border-radius:9px;background:rgba(0,0,0,.07)}.report-spec span{display:block;color:#5c7166;font-size:7px;text-transform:uppercase}.report-spec strong{display:block;margin-top:4px;font-size:8px}
.report-card-actions{display:flex;align-items:center;justify-content:space-between;gap:7px;margin-top:10px}.report-status{font-size:7px;color:#63796d;font-weight:900}.report-session{margin-top:10px;padding:10px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.01);display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7px;color:#60766b}.report-session strong{color:#93a99d}
.website-shell{display:grid;grid-template-columns:170px minmax(0,1fr) 300px;gap:10px}.website-nav{display:grid;gap:5px;height:max-content}.website-tab{display:flex;align-items:center;gap:8px;border:1px solid var(--line-soft);background:rgba(255,255,255,.012);color:#70877b;border-radius:10px;padding:9px 10px;text-align:left;font-size:8px;font-weight:900}.website-tab.active{background:rgba(37,219,117,.06);border-color:rgba(37,219,117,.13);color:#a7d8b8}.website-editor{min-width:0}.website-pane{display:none}.website-pane.active{display:block}
.website-preview{height:max-content;border:1px solid rgba(62,101,84,.24);border-radius:14px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}.website-preview-head{padding:10px 11px;border-bottom:1px solid var(--line-soft);display:flex;align-items:center;justify-content:space-between;gap:7px}.website-preview-head strong{font-size:9px}.member-preview{padding:11px}.member-preview-device{border:1px solid var(--line);border-radius:14px;background:#08100e;overflow:hidden}.member-preview-top{height:36px;padding:0 10px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line-soft);font-size:8px;font-weight:950}.member-preview-banner{height:98px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(37,219,117,.10),rgba(216,180,95,.05));color:#62786d;font-size:7px;font-weight:900;overflow:hidden}.member-preview-banner img{width:100%;height:100%;object-fit:cover}.member-preview-body{padding:9px}.member-preview-announcement,.member-preview-seo{padding:8px;border:1px solid var(--line-soft);border-radius:9px;color:#687f73;font-size:7px;line-height:1.4}.member-preview-seo{margin-top:8px}.member-preview-seo strong{display:block;font-size:8px}.member-preview-seo span{display:block;margin-top:4px;color:#5c7166;font-size:7px}
.security-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,.8fr);gap:10px}.permission-list,.config-list{display:grid;gap:7px}.permission-row,.config-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;padding:9px;border:1px solid var(--line-soft);border-radius:10px;background:rgba(255,255,255,.012)}.permission-row strong,.config-row strong{display:block;font-size:8px}.permission-row span,.config-row span{display:block;margin-top:3px;color:#5b7166;font-size:7px}.security-note{margin-top:10px;padding:11px;border:1px solid rgba(37,219,117,.1);border-radius:11px;background:rgba(37,219,117,.025);color:#658073;font-size:7px;line-height:1.5}
.audit-shell{border:1px solid rgba(62,101,84,.24);border-radius:14px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}.audit-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 160px auto;gap:7px;padding:10px;border-bottom:1px solid var(--line-soft)}.audit-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 10px;border-bottom:1px solid var(--line-soft);font-size:7px;color:#60766b}.audit-meta strong{color:#91a79b}.audit-mobile-list{display:none;padding:9px;gap:8px}.audit-mobile-card{padding:11px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.012)}.audit-mobile-head{display:flex;align-items:center;gap:8px}.audit-mobile-head strong{min-width:0;flex:1;font-size:9px;overflow:hidden;text-overflow:ellipsis}.audit-mobile-sub{margin-top:4px;color:#5d7368;font-size:7px}.audit-mobile-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:9px}.audit-mobile-kv{padding:8px;border:1px solid var(--line-soft);border-radius:9px;background:rgba(0,0,0,.08)}.audit-mobile-kv span{display:block;color:#5d7368;font-size:7px;text-transform:uppercase}.audit-mobile-kv strong{display:block;margin-top:4px;font-size:8px;overflow:hidden;text-overflow:ellipsis}.audit-mobile-actions{display:flex;justify-content:flex-end;margin-top:8px}
@media(max-width:1180px){.payment-layout,.security-layout{grid-template-columns:1fr}.website-shell{grid-template-columns:150px minmax(0,1fr)}.website-preview{grid-column:1/-1}.system-stats,.security-grid,.audit-stats{grid-template-columns:repeat(2,1fr)}}
@media(max-width:860px){.report-grid{grid-template-columns:1fr}.website-shell{grid-template-columns:1fr}.website-nav{grid-template-columns:repeat(4,1fr);overflow:auto}.website-tab{justify-content:center;white-space:nowrap}.payment-connection-meta{grid-template-columns:1fr 1fr}}
@media(max-width:760px){.system-hero{align-items:flex-start;flex-direction:column}.system-hero-actions{width:100%}.system-stats,.security-grid,.audit-stats{grid-template-columns:1fr 1fr}.audit-toolbar{grid-template-columns:1fr 1fr}.audit-toolbar .search-box{grid-column:1/-1}.audit-shell .table-wrap{display:none}.audit-mobile-list{display:grid}.website-nav{grid-template-columns:1fr 1fr}}


/* ===== V4 CLOUDFLARE + FIREBASE PRODUCTION ===== */
.auth-boot{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:#08100e;transition:opacity .12s ease,visibility .12s ease}
.auth-boot.hidden{opacity:0;visibility:hidden;pointer-events:none}
.auth-boot-card{display:flex;align-items:center;gap:11px;padding:12px 15px;border:1px solid rgba(83,126,106,.18);border-radius:14px;background:rgba(13,23,19,.96);box-shadow:0 18px 50px rgba(0,0,0,.28)}
.auth-boot-logo{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:rgba(37,219,117,.08);border:1px solid rgba(37,219,117,.13);color:#78d99a;font-size:11px;font-weight:950}
.auth-boot-copy strong{display:block;font-size:9px;color:#dce9e2}.auth-boot-copy span{display:block;margin-top:3px;font-size:7px;color:#5f756a}
.auth-boot-spinner{width:15px;height:15px;border:2px solid rgba(255,255,255,.08);border-top-color:#63d98b;border-radius:50%;animation:authspin .65s linear infinite}
@keyframes authspin{to{transform:rotate(360deg)}}



/* ===== V3.6 MEMBER GAME CURATION ===== */
.catalog-admin-tabs{display:flex;gap:6px;overflow-x:auto;padding:0 0 9px;scrollbar-width:none}.catalog-admin-tabs::-webkit-scrollbar{display:none}
.catalog-admin-tab{flex:0 0 auto;border:1px solid var(--line-soft);background:rgba(255,255,255,.012);color:#6d8378;border-radius:10px;padding:8px 11px;font-size:8px;font-weight:950;cursor:pointer}
.catalog-admin-tab.active{border-color:rgba(37,219,117,.18);background:rgba(37,219,117,.065);color:#b4e7c5}
.catalog-pane{display:none}.catalog-pane.active{display:block}
.catalog-config-bar{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-bottom:9px;padding:10px 11px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012)}
.catalog-config-copy strong{display:block;font-size:9px}.catalog-config-copy span{display:block;margin-top:3px;color:#62796d;font-size:7px;line-height:1.45}
.catalog-save-wrap{display:flex;align-items:center;gap:7px}.catalog-dirty{font-size:7px;font-weight:950;color:#71877b}.catalog-dirty.changed{color:#d9c17a}
.curation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:9px}.curation-card{min-width:0;padding:10px;border:1px solid var(--line-soft);border-radius:12px;background:rgba(255,255,255,.012)}
.curation-head{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:7px}.curation-head strong{font-size:8.5px}.curation-head span{font-size:7px;color:#61776c;font-weight:900}
.curation-list{display:grid;gap:5px;max-height:240px;overflow:auto}.curation-empty{padding:12px 8px;border:1px dashed var(--line-soft);border-radius:9px;text-align:center;color:#5e7469;font-size:7px}
.curation-item{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px;align-items:center;padding:7px;border:1px solid var(--line-soft);border-radius:9px;background:rgba(0,0,0,.08)}.curation-item strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:7.8px}.curation-item span{display:block;margin-top:2px;color:#5f756a;font-size:6.8px}.curation-move{display:flex;gap:3px}.curation-move button{width:25px;height:25px;border:1px solid var(--line-soft);border-radius:7px;background:rgba(255,255,255,.02);color:#789084;font-size:10px;cursor:pointer}
.display-game-shell,.provider-order-shell{border:1px solid rgba(62,101,84,.24);border-radius:14px;background:linear-gradient(155deg,rgba(13,23,19,.98),rgba(9,17,14,.98));overflow:hidden}.display-game-toolbar{display:grid;grid-template-columns:minmax(180px,1fr) auto;gap:7px;padding:10px;border-bottom:1px solid var(--line-soft)}
.display-game-list,.provider-order-list{display:grid;gap:7px;padding:9px}.display-game-row,.provider-order-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:9px;align-items:center;padding:9px;border:1px solid var(--line-soft);border-radius:11px;background:rgba(255,255,255,.012)}
.display-game-main,.provider-order-main{min-width:0;display:flex;align-items:center;gap:8px}.display-game-thumb{width:38px;height:44px;flex:0 0 38px;border-radius:8px;overflow:hidden;border:1px solid var(--line-soft);background:#07150f;display:grid;place-items:center;color:#5c7568;font-size:7px}.display-game-thumb img{width:100%;height:100%;object-fit:cover}.display-game-copy,.provider-order-copy{min-width:0}.display-game-copy strong,.provider-order-copy strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:8.5px}.display-game-copy span,.provider-order-copy span{display:block;margin-top:3px;color:#5f756a;font-size:7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.display-game-actions,.provider-order-actions{display:flex;align-items:center;justify-content:flex-end;gap:4px;flex-wrap:wrap}.catalog-toggle{min-height:27px;padding:0 7px;border:1px solid var(--line-soft);border-radius:8px;background:rgba(255,255,255,.015);color:#63796d;font-size:6.7px;font-weight:950;cursor:pointer}.catalog-toggle.on{border-color:rgba(37,219,117,.22);background:rgba(37,219,117,.065);color:#aee5c1}.catalog-toggle.warn.on{border-color:rgba(216,180,95,.22);background:rgba(216,180,95,.06);color:#d9c17a}.provider-position{width:27px;height:27px;border:1px solid var(--line-soft);border-radius:8px;background:rgba(255,255,255,.015);color:#789084;cursor:pointer}
.catalog-curation-note{margin:0 0 9px;padding:9px 10px;border:1px solid rgba(37,219,117,.09);border-radius:10px;background:rgba(37,219,117,.02);color:#61796d;font-size:7px;line-height:1.5}
@media(max-width:900px){.curation-grid{grid-template-columns:1fr}.display-game-row,.provider-order-row{grid-template-columns:1fr}.display-game-actions,.provider-order-actions{justify-content:flex-start}.display-game-toolbar{grid-template-columns:1fr}.catalog-config-bar{align-items:flex-start;flex-direction:column}.catalog-save-wrap{width:100%;justify-content:space-between}}


/* V3.6 fast catalog rendering + modern operational controls */
.catalog-pager{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-top:1px solid var(--line-soft);background:rgba(255,255,255,.008)}
.catalog-pager>span{color:#667c70;font-size:7.5px;font-weight:900;letter-spacing:.35px}.catalog-pager>div{display:flex;gap:6px}.catalog-pager button:disabled{opacity:.38;cursor:not-allowed}
.display-game-row,.game-mobile-card,.provider-order-row,.curation-item{content-visibility:auto;contain-intrinsic-size:72px}
.catalog-admin-tab,.provider-position,.catalog-toggle{transition:transform .14s ease,border-color .14s ease,background .14s ease}.catalog-admin-tab:active,.provider-position:active,.catalog-toggle:active{transform:scale(.97)}
@media(max-width:720px){.catalog-pager{position:sticky;bottom:0;z-index:8;backdrop-filter:blur(14px);background:rgba(6,16,12,.94)}.catalog-pager .btn{min-height:34px;padding-inline:9px}}

body.script:
//
    import { initializeApp } from 'https://www.gstatic.com/firebasejs/12.4.0/firebase-app.js';
    import { getAuth, onAuthStateChanged, signInWithEmailAndPassword, signOut, setPersistence, browserSessionPersistence } from 'https://www.gstatic.com/firebasejs/12.4.0/firebase-auth.js';

    const firebaseConfig={
      apiKey:'AIzaSyAdndUMKN1KQjoMw0ZRL-2h-m32E_q6ris',
      authDomain:'brandal-bet.firebaseapp.com',
      projectId:'brandal-bet',
      storageBucket:'brandal-bet.firebasestorage.app',
      messagingSenderId:'38183964058',
      appId:'1:38183964058:web:2b128da5582e6932c73e23'
    };

    const API_BASE=(document.querySelector("meta[name='brandalbet-api-base']")?.content||'https://brandalbet-backend.rkmpbajangda.workers.dev').replace(/\/+$/,'');
    const ENDPOINTS={
      health:'/api/backoffice-health',
      master:'/api/backoffice-master-control',
      readiness:'/api/backoffice-readiness',
      bootstrap:'/api/bootstrap-superadmin',
      promotions:'/api/backoffice-promotions',
      rewards:'/api/backoffice-rewards',
      dashboard:'/api/backoffice-dashboard',
      members:'/api/backoffice-members',
      finance:'/api/backoffice-finance',
      ledger:'/api/backoffice-ledger',
      deposits:'/api/backoffice-finance',
      withdrawals:'/api/backoffice-finance',
      reconciliation:'/api/backoffice-finance',
      catalog:'/api/backoffice-game-catalog',
      provider:'/api/backoffice-provider',
      payment:'/api/backoffice-payment-connections',
      reports:'/api/backoffice-reports',
      website:'/api/backoffice-website-settings',
      audit:'/api/backoffice-audit'
    };

    const app=initializeApp(firebaseConfig);
    const auth=getAuth(app);
    // Keep the authenticated admin session across page reloads in this browser session.
    // The session ends when the browser session is closed or the admin logs out.
    try{await setPersistence(auth,browserSessionPersistence)}catch{}
    const $=q=>document.querySelector(q);
    const $$=q=>[...document.querySelectorAll(q)];
    let currentUser=null;
    let currentRole='';
    let enterPromise=null;
    let promoCache=[];
    let providerCapabilities={};
    let readinessCache={};
    let auditCache=[];
    let reportSession=[];
    let masterControlState={maintenanceMode:false,gameLaunchEnabled:true,registrationEnabled:true,promotionsEnabled:true,memberWalletEnabled:true,maintenanceMessage:'',revision:0};

    const titles={
      master:['Master Control',''],
      dashboard:['Dashboard',''],
      members:['Members',''],
      finance:['Finance Ops',''],
      deposits:['Deposits',''],
      withdrawals:['Withdrawals',''],
      reconciliation:['Reconciliation',''],
      catalog:['Game Catalog',''],
      provider:['GoldslotPalase',''],
      rtp:['RTP / Game Controls',''],
      'provider-health':['Provider Health',''],
      promotions:['Promotions',''],
      rewards:['Rewards / Referral / Cashback',''],
      payment:['Payment Gateway',''],
      reports:['Reports',''],
      website:['Website Settings',''],
      security:['Admin & Security',''],
      audit:['Audit Log','']
    };

    function busy(v){$('#loader').classList.toggle('show',!!v)}
    function toast(message,type=''){const root=$('#toastRoot');const el=document.createElement('div');el.className='toast '+type;el.textContent=message;root.appendChild(el);setTimeout(()=>el.remove(),4200)}
    function loginNotice(message,ok=false){$('#loginNotice').innerHTML=message?`<div class="notice ${ok?'ok':''}">${escapeHtml(message)}</div>`:''}
    function firebaseLoginMessage(err){
      const code=String(err?.code||'');
      if(code==='auth/invalid-email')return 'Format email admin tidak valid.';
      if(code==='auth/invalid-credential'||code==='auth/user-not-found'||code==='auth/wrong-password')return 'Email atau password Firebase admin tidak cocok.';
      if(code==='auth/user-disabled')return 'Akun Firebase admin ini dinonaktifkan.';
      if(code==='auth/too-many-requests')return 'Login sementara dibatasi Firebase karena terlalu banyak percobaan. Coba kembali setelah beberapa saat.';
      if(code==='auth/network-request-failed')return 'Koneksi ke Firebase gagal. Periksa jaringan internet.';
      if(code==='auth/operation-not-allowed')return 'Metode Email/Password belum diaktifkan pada Firebase Authentication.';
      return 'Login Firebase gagal: '+(code||err?.message||'unknown_error');
    }
    function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
    function fmtMoney(v){const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n):'—'}
    function fmtDate(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(d)}
    function stateChip(v){const s=String(v||'unknown').toLowerCase();const cls=['active','paid','success','healthy','ok','enabled'].includes(s)?'green':['failed','blocked','rejected','error','down'].includes(s)?'red':'gold';return `<span class="chip ${cls}">${escapeHtml(String(v||'unknown').toUpperCase())}</span>`}
    function queryString(obj){const p=new URLSearchParams();Object.entries(obj||{}).forEach(([k,v])=>{if(v!==''&&v!==null&&v!==undefined)p.set(k,String(v))});const q=p.toString();return q?'?'+q:''}

    const BACKEND_TIMEOUT_MS=12000;

    async function token(force=false){if(!currentUser)throw new Error('not_authenticated');return currentUser.getIdToken(force)}
    async function backendFetch(path,{method='GET',tokenValue,body,query,headers={}}={}){
      const controller=new AbortController();
      const timer=setTimeout(()=>controller.abort(),BACKEND_TIMEOUT_MS);
      try{
        const r=await fetch(API_BASE+path+queryString(query),{
          method,
          mode:'cors',
          headers:{Accept:'application/json',...(tokenValue?{Authorization:`Bearer ${tokenValue}`}:{...{}}),...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},
          body:body===undefined?undefined:JSON.stringify(body),
          cache:'no-store',
          credentials:'omit',
          signal:controller.signal
        });
        let data={};try{data=await r.json()}catch{}
        if(!r.ok)throw Object.assign(new Error(data.error||data.message||`HTTP ${r.status}`),{status:r.status,data});
        return data;
      }catch(err){
        if(err?.name==='AbortError')throw Object.assign(new Error('backend_timeout'),{network:true});
        if(!err?.status && err instanceof TypeError)err.network=true;
        throw err;
      }finally{clearTimeout(timer)}
    }

    async function backendLiveness(){return backendFetch('/api/health')}
    async function api(name,{method='GET',body,query,headers={}}={}){
      const t=await token();
      const path=ENDPOINTS[name]||name;
      return backendFetch(path,{method,tokenValue:t,body,query,headers});
    }

    async function authorize(user){
      const t=await user.getIdToken();
      return backendFetch(ENDPOINTS.health,{tokenValue:t});
    }
    async function bootstrap(user){
      const t=await user.getIdToken();
      const data=await backendFetch(ENDPOINTS.bootstrap,{method:'POST',tokenValue:t});
      await user.getIdToken(true);
      return data;
    }

    const screenRoles={
      master:['admin','superadmin'],
      dashboard:['operator','finance','admin','superadmin'],
      members:['operator','admin','superadmin'],
      finance:['finance','admin','superadmin'],
      deposits:['finance','admin','superadmin'],
      withdrawals:['finance','admin','superadmin'],
      reconciliation:['finance','admin','superadmin'],
      catalog:['operator','admin','superadmin'],
      provider:['operator','admin','superadmin'],
      rtp:['operator','admin','superadmin'],
      'provider-health':['operator','admin','superadmin'],
      promotions:['operator','admin','superadmin'],
      rewards:['finance','admin','superadmin'],
      payment:['admin','superadmin'],
      reports:['finance','admin','superadmin'],
      website:['operator','finance','admin','superadmin'],
      security:['operator','finance','admin','superadmin'],
      audit:['admin','superadmin']
    };
    function canOpen(name,role=currentRole){return (screenRoles[name]||[]).includes(role)}
    function applyRoleUI(role){
      currentRole=role;
      if($('#dashboardRoleLabel'))$('#dashboardRoleLabel').textContent=String(role||'authorized').toUpperCase();
      $$('.nav-btn[data-screen]').forEach(b=>b.classList.toggle('hidden',!canOpen(b.dataset.screen,role)));
      $$('[data-go]').forEach(b=>b.classList.toggle('hidden',!canOpen(b.dataset.go,role)));
      $$('[data-save-setting]').forEach(b=>b.classList.toggle('hidden',!['admin','superadmin'].includes(role)));
      $('#newGatewayBtn')?.classList.toggle('hidden',!['admin','superadmin'].includes(role));
      $('#rewardReferralAdmin')?.classList.toggle('hidden',!['admin','superadmin'].includes(role));
      $('#catalogSyncBtn')?.classList.toggle('hidden',!['admin','superadmin'].includes(role));
      $('#providerServerCheck')?.classList.toggle('hidden',!['admin','superadmin'].includes(role));
      $('#providerSyncTx')?.classList.toggle('hidden',!['admin','superadmin'].includes(role));
      $$('[data-export="member"]').forEach(b=>b.classList.toggle('hidden',!['admin','superadmin'].includes(role)));
      if($('#websiteAccessLabel'))$('#websiteAccessLabel').textContent=['admin','superadmin'].includes(role)?'EDIT ACCESS':'READ ONLY';
      if($('#reportMemberStatus'))$('#reportMemberStatus').textContent=['admin','superadmin'].includes(role)?'READY':'ADMIN ONLY';
    }
    function closeDrawer(){
      document.body.classList.remove('drawer-open');
      $('#sidebar').classList.remove('open');
      $('#drawerBackdrop').classList.remove('show');
    }
    function hideAuthBoot(){const b=$('#authBoot');if(b)b.classList.add('hidden')}
    function showLoginScreen({resetRoute=false}={}){
      currentUser=null;
      currentRole='';
      closeDrawer();
      $('#adminShell').classList.add('hidden');
      $('#loginShell').classList.remove('hidden');
      $('#password').value='';
      if(resetRoute)history.replaceState(null,'','#dashboard');
      hideAuthBoot();
    }
    function openDrawer(){
      document.body.classList.add('drawer-open');
      $('#sidebar').classList.add('open');
      $('#drawerBackdrop').classList.add('show');
    }
    function openScreen(name){
      if(!titles[name]||!canOpen(name))name='dashboard';
      $$('.screen').forEach(el=>el.classList.toggle('active',el.dataset.screen===name));
      $$('.nav-btn').forEach(el=>el.classList.toggle('active',el.dataset.screen===name));
      $('#screenTitle').textContent=titles[name][0];
      $('#screenCaption').textContent='';
      closeDrawer();
      history.replaceState(null,'','#'+name);
      if(name==='master'&&currentUser)setTimeout(loadMasterControl,0);
      if(name==='members'&&currentUser&&memberCache.length===0)setTimeout(loadMembers,0);
      if(name==='finance'&&currentUser){setTimeout(loadFinanceSuite,0);if(ledgerCache.length===0)setTimeout(loadLedger,0)}
      if(name==='deposits'&&currentUser&&depositCache.length===0)setTimeout(loadDeposits,0);
      if(name==='withdrawals'&&currentUser&&withdrawCache.length===0)setTimeout(loadWithdrawals,0);
      if(name==='reconciliation'&&currentUser&&reconCache.length===0)setTimeout(loadReconciliation,0);
      if(name==='catalog'&&currentUser&&catalogCache.length===0)setTimeout(()=>loadCatalog(false),0);
      if(name==='promotions'&&currentUser)loadPromotions();
      if(name==='rewards'&&currentUser)setTimeout(loadRewards,0);
      if(name==='payment'&&currentUser)setTimeout(loadPayment,0);
      if(name==='website'&&currentUser)setTimeout(loadWebsite,0);
      if(name==='security'&&currentUser){setTimeout(()=>loadReadiness(currentRole),0);setTimeout(renderSecurityCenter,0)}
      if(name==='audit'&&currentUser&&auditCache.length===0)setTimeout(loadAudit,0);
      if(['provider','provider-health','rtp'].includes(name)&&currentUser)setTimeout(loadProvider,0);
    }

    $('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(b)openScreen(b.dataset.screen)});
    $$('[data-go]').forEach(b=>b.addEventListener('click',()=>openScreen(b.dataset.go)));

    const menuIndex=Object.entries(titles).map(([key,val])=>({key,label:(val[0]+' '+val[1]).toLowerCase()}));
    $('#globalSearch').addEventListener('input',e=>{
      const q=e.target.value.trim().toLowerCase();
      if(!q)return;
      const hit=menuIndex.find(x=>x.label.includes(q));
      if(hit&&q.length>=3)openScreen(hit.key);
    });
    $('#topDate').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date());

    function prettyKey(k){return String(k).replace(/([A-Z])/g,' $1').replace(/[_-]/g,' ').replace(/^./,m=>m.toUpperCase())}
    function openDetail(type,data){
      $('#detailTitle').textContent=type==='Member'?'Member Profile':type+' Detail';
      $('#detailSubtitle').textContent=data.reference||data.username||data.name||data.uid||'Operational record';
      if(type==='Member'){
        const display=data.username||data.displayName||data.email||data.uid||'Member',initial=escapeHtml((String(display)[0]||'M').toUpperCase());
        $('#detailBody').innerHTML=`<div class="member-detail-hero"><div class="member-detail-avatar">${initial}</div><div class="member-detail-name"><h4>${escapeHtml(display)}</h4><span>${escapeHtml(data.email||data.uid||'—')}</span></div>${stateChip(data.status)}</div><div class="detail-section"><div class="detail-section-title">Wallet</div><div class="member-detail-wallet"><div class="wallet-box"><span>Total Balance</span><strong>${fmtMoney(data.balance)}</strong></div><div class="wallet-box"><span>Available Balance</span><strong>${fmtMoney(data.availableBalance)}</strong></div></div></div><div class="detail-section"><div class="detail-section-title">Account</div><div class="detail-grid"><div class="detail-kv"><span>UID</span><strong>${escapeHtml(data.uid||'—')}</strong></div><div class="detail-kv"><span>Username</span><strong>${escapeHtml(data.username||'—')}</strong></div><div class="detail-kv"><span>Display Name</span><strong>${escapeHtml(data.displayName||'—')}</strong></div><div class="detail-kv"><span>Email</span><strong>${escapeHtml(data.email||'—')}</strong></div><div class="detail-kv"><span>Onboarding</span><strong>${data.onboardingCompleted===true?'Complete':'Pending'}</strong></div><div class="detail-kv"><span>Registered</span><strong>${fmtDate(data.createdAt)}</strong></div></div></div><div class="detail-section"><button class="copy-uid" data-copy-uid="${escapeHtml(data.uid||'')}" type="button">Copy UID</button></div>`;
      }else if(type==='Audit'){
        $('#detailBody').innerHTML=`<div class="finance-detail-hero"><div class="finance-detail-ref">${escapeHtml(data.action||'Audit Event')}</div><div class="finance-detail-sub">${escapeHtml(data.actor||'—')} • ${fmtDate(data.createdAt||data.time)}</div><div style="margin-top:9px">${stateChip(data.result||data.status)}</div></div><div class="detail-section"><div class="detail-section-title">Audit Information</div><div class="detail-grid"><div class="detail-kv"><span>Actor</span><strong>${escapeHtml(data.actor||'—')}</strong></div><div class="detail-kv"><span>Action</span><strong>${escapeHtml(data.action||'—')}</strong></div><div class="detail-kv"><span>Resource</span><strong>${escapeHtml(data.resource||'—')}</strong></div><div class="detail-kv"><span>Request ID</span><strong>${escapeHtml(data.requestId||'—')}</strong></div><div class="detail-kv"><span>Revision</span><strong>${data.revision==null?'—':escapeHtml(String(data.revision))}</strong></div><div class="detail-kv"><span>Created</span><strong>${fmtDate(data.createdAt||data.time)}</strong></div></div></div>`;
      }else if(type==='Game'){
        const name=data.name||data.code||'Game';
        $('#detailBody').innerHTML=`<div class="game-detail-hero"><div class="game-detail-icon">G</div><div class="game-detail-copy"><h4>${escapeHtml(name)}</h4><span>${escapeHtml(data.code||'—')} • ${escapeHtml(data.providerName||'GoldslotPalase')}</span></div>${stateChip(data.providerStatus)}</div><div class="detail-section"><div class="detail-section-title">Game Information</div><div class="detail-grid"><div class="detail-kv"><span>Code</span><strong>${escapeHtml(data.code||'—')}</strong></div><div class="detail-kv"><span>Category</span><strong>${escapeHtml(data.category||'—')}</strong></div><div class="detail-kv"><span>Provider</span><strong>${escapeHtml(data.providerName||'GoldslotPalase')}</strong></div><div class="detail-kv"><span>Provider ID</span><strong>${escapeHtml(data.providerId||'—')}</strong></div><div class="detail-kv"><span>Launch Status</span><strong>${escapeHtml(data.providerStatus||'—')}</strong></div><div class="detail-kv"><span>Visible</span><strong>${data.visible?'Yes':'No'}</strong></div><div class="detail-kv"><span>Updated</span><strong>${fmtDate(data.updatedAt)}</strong></div></div></div><div class="detail-section"><div class="safe-note">Catalog dan launch state berasal dari backend GoldslotPalase. Tidak ada credential provider di Blogger XML.</div></div>`;
      }else if(['Deposit','Withdrawal','Reconciliation'].includes(type)){
        const ref=data.reference||data.id||'—';
        const amount=type==='Reconciliation'?data.internalAmount:data.amount;
        $('#detailBody').innerHTML=`<div class="finance-detail-hero"><div class="finance-detail-ref">${escapeHtml(ref)}</div><div class="finance-detail-sub">${escapeHtml(type)} • server record</div><div class="finance-detail-amount">${fmtMoney(amount)}</div><div style="margin-top:9px">${stateChip(data.status)}</div></div><div class="detail-section"><div class="detail-section-title">Transaction</div><div class="detail-grid">${Object.entries(data||{}).filter(([k,v])=>v!==null&&v!==undefined&&typeof v!=='object').slice(0,18).map(([k,v])=>`<div class="detail-kv"><span>${escapeHtml(prettyKey(k))}</span><strong>${['amount','internalAmount','externalAmount','difference'].includes(k)?fmtMoney(v):escapeHtml(String(v))}</strong></div>`).join('')}</div></div><div class="detail-section"><div class="safe-note">Backoffice tidak melakukan mutasi saldo dari browser. Tindakan finansial tetap membutuhkan adapter backend, idempotency, RBAC, dan audit.</div></div>`;
      }else{
        const entries=Object.entries(data||{}).filter(([k,v])=>v!==null&&v!==undefined&&typeof v!=='object').slice(0,20);
        $('#detailBody').innerHTML=`<div class="detail-section"><div class="detail-section-title">Record information</div><div class="detail-grid">${entries.map(([k,v])=>`<div class="detail-kv"><span>${escapeHtml(prettyKey(k))}</span><strong>${escapeHtml(String(v))}</strong></div>`).join('')}</div></div>`;
      }
      $('#detailOverlay').classList.add('show');$('#detailDrawer').classList.add('show');
    }
    function closeDetail(){$('#detailOverlay').classList.remove('show');$('#detailDrawer').classList.remove('show')}
    document.addEventListener('click',e=>{
      const b=e.target.closest('[data-detail]');
      if(!b)return;
      try{openDetail(b.dataset.detailType||'Record',JSON.parse(decodeURIComponent(b.dataset.detail)))}catch{toast('Detail record tidak dapat dibaca.','error')}
    });
    $('#detailOverlay').addEventListener('click',closeDetail);$('#detailClose').addEventListener('click',closeDetail);$('#detailDismiss').addEventListener('click',closeDetail);
    $('#detailBody').addEventListener('click',async e=>{const b=e.target.closest('[data-copy-uid]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copyUid);toast('UID disalin.','ok')}catch{toast('Gagal menyalin UID.','error')}});
    document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});
    $('#menuBtn').addEventListener('click',openDrawer);
    $('#drawerClose').addEventListener('click',closeDrawer);
    $('#drawerBackdrop').addEventListener('click',closeDrawer);

    async function loadReadiness(role=currentRole){
      if(!['admin','superadmin'].includes(role))return;
      try{
        const d=await api('readiness');
        const r=d.readiness||{};
        readinessCache=r;
        const config=Array.isArray(r.configuration)?r.configuration:[];
        const missing=config.filter(x=>x.present!==true);
        $('#paymentText').textContent=r.integrations?.payment||'Payment readiness unknown';
        $('#paymentState').textContent=r.integrations?.payment?.includes('pending')?'PENDING':'CHECK';
        $('#auditText').textContent=missing.length?`${missing.length} configuration item belum tersedia.`:'Core configuration terdeteksi.';
        $('#auditState').textContent=missing.length?'CONFIG':'OK';
        $('#auditState').className='mini-state '+(missing.length?'warn':'ok');
        $('#backendPill').textContent=missing.length?`BACKEND • ${missing.length} CONFIG`:'BACKEND VERIFIED';
        if(typeof renderSecurityCenter==='function')renderSecurityCenter();
      }catch(err){
        if(err.status!==403)toast('Readiness check gagal: '+err.message,'error');
      }
    }

    async function enter(user){
      if(enterPromise)return enterPromise;
      enterPromise=(async()=>{
        busy(true);
        let livenessPassed=false;
        try{
          await backendLiveness();
          livenessPassed=true;
          try{await authorize(user)}
          catch(first){
            if(first.status!==403)throw first;
            try{
              const boot=await bootstrap(user);
              if(!boot?.ok)throw first;
              await authorize(user);
            }catch(bootErr){
              // Bootstrap is intentionally disabled after first use. Preserve the
              // original 403 so the UI reports missing RBAC instead of a fake 404.
              if(bootErr?.status===404||bootErr?.status===403)throw first;
              throw bootErr;
            }
          }
          const tr=await user.getIdTokenResult(true);
          const role=String(tr.claims.role||'backoffice');
          currentUser=user;
          applyRoleUI(role);
          $('#roleBadge').textContent=role.toUpperCase();
          $('#sideUserRole').textContent=role.toUpperCase();
          $('#sideUserName').textContent=user.email||'Administrator';
          $('#sideAvatar').textContent=(user.email||'A').slice(0,1).toUpperCase();
          $('#securityEmail').textContent=user.email||'—';
          $('#securityUid').textContent='UID '+user.uid;
          $('#securityRole').textContent=role.toUpperCase();
          $('#backendPill').textContent='BACKEND VERIFIED';
          $('#rbacText').textContent='Firebase ID Token dan backoffice claim terverifikasi.';
          $('#rbacState').textContent='OK';$('#rbacState').className='mini-state ok';
          $('#loginShell').classList.add('hidden');
          $('#adminShell').classList.remove('hidden');
          hideAuthBoot();
          loginNotice('');
          const requested=(location.hash||'').slice(1);
          const defaultScreen=['admin','superadmin'].includes(role)?'master':'dashboard';
          openScreen(requested&&requested!=='dashboard'?requested:defaultScreen);
          await Promise.allSettled([loadDashboard(),loadReadiness(role),['admin','superadmin'].includes(role)?loadMasterControl():Promise.resolve()]);
          return true;
        }catch(err){
          showLoginScreen({resetRoute:true});
          $('#backendPill').textContent='ACCESS DENIED';
          const backendHost=(()=>{try{return new URL(API_BASE).host}catch{return API_BASE}})();
          if(err?.network||(!err?.status&&(String(err?.message||'').includes('Failed to fetch')||String(err?.message||'').includes('NetworkError')))){
            loginNotice(livenessPassed
              ?`Cloudflare Worker hidup, tetapi endpoint backoffice diblokir/tidak dapat diakses browser. Target: ${backendHost}.`
              :`Browser tidak dapat menjangkau Cloudflare Worker. Periksa URL production/deployment. Target: ${backendHost}.`);
          }else if(err.status===401)loginNotice('Token Firebase admin tidak valid/kedaluwarsa atau konfigurasi Firebase Admin tidak cocok.');
          else if(err.status===403)loginNotice('Login Firebase berhasil, tetapi akun belum memiliki claim backoffice. Pastikan UID superadmin dibootstrap sekali.');
          else if(err.status===404)loginNotice('Route backoffice tidak tersedia pada deployment Cloudflare Worker aktif.');
          else if(err.status===503)loginNotice('Firebase Admin backend belum siap. Periksa binding kredensial Firebase Admin dan project ID pada Cloudflare Worker.');
          else loginNotice('Akses backoffice gagal: '+(err.message||'unknown'));
          try{await signOut(auth)}catch{}
          return false;
        }finally{busy(false)}
      })();
      try{return await enterPromise}finally{enterPromise=null}
    }

    $('#loginForm').addEventListener('submit',async e=>{
      e.preventDefault();loginNotice('');busy(true);
      const submit=$('#loginSubmit');
      submit.disabled=true;$('#loginSubmitText').textContent='Memverifikasi…';
      try{
        const cred=await signInWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);
        loginNotice('Login berhasil. Membuka dashboard…',true);
        await enter(cred.user);
      }catch(err){
        loginNotice(firebaseLoginMessage(err));
      }finally{
        $('#password').value='';
        submit.disabled=false;$('#loginSubmitText').textContent='Masuk ke Backoffice';
        busy(false);
      }
    });
    $('#togglePassword').addEventListener('click',e=>{
      e.preventDefault();
      const input=$('#password');
      const button=e.currentTarget;
      const show=input.type==='password';
      input.type=show?'text':'password';
      button.classList.toggle('active',show);
      button.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');
      $('#togglePasswordIcon').innerHTML=show?"<path d='m3 3 18 18'/><path d='M10.6 10.7a3 3 0 0 0 4.2 4.2'/><path d='M9.9 5.1A11.5 11.5 0 0 1 12 5c6.5 0 10 7 10 7a17.7 17.7 0 0 1-4.1 4.8'/><path d='M6.2 6.3A17.3 17.3 0 0 0 2 12s3.5 7 10 7a10.7 10.7 0 0 0 3.2-.5'/>":"<path d='M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z'/><circle cx='12' cy='12' r='3'/>";
      input.focus();
    });
    $('#logoutBtn').addEventListener('click',async()=>{
      try{await signOut(auth)}catch{}
      showLoginScreen({resetRoute:true});
    });
    onAuthStateChanged(auth,async user=>{
      if(user){
        try{
          // Restore the current route; admin/superadmin defaults to Master Control.
          await enter(user);
        }catch{
          showLoginScreen({resetRoute:true});
        }
      }else{
        showLoginScreen({resetRoute:true});
      }
    });

    /* MASTER CONTROL */
    function renderMasterControl(provider=null,readiness=null){
      const c=masterControlState||{};
      $('#masterMaintenance').value=String(c.maintenanceMode===true);
      $('#masterGameLaunch').value=String(c.gameLaunchEnabled!==false);
      $('#masterRegistration').value=String(c.registrationEnabled!==false);
      $('#masterPromotions').value=String(c.promotionsEnabled!==false);
      $('#masterMemberWallet').value=String(c.memberWalletEnabled!==false);
      $('#masterMessage').value=c.maintenanceMessage||'';
      $('#masterRevision').textContent=String(Number(c.revision||0));
      $('#masterUpdatedAt').textContent=fmtDate(c.updatedAt);
      $('#masterUpdatedBy').textContent=c.updatedBy||'SYSTEM';
      $('#masterCurrentRole').textContent=String(currentRole||'—').toUpperCase();
      $('#masterBackendState').textContent=currentUser?'VERIFIED':'OFFLINE';
      const badge=$('#masterModeBadge');
      badge.textContent=c.maintenanceMode===true?'MAINTENANCE MODE':'LIVE MODE';
      badge.classList.toggle('warn',c.maintenanceMode===true);
      const r=readiness&&readiness.readiness?readiness.readiness:(readiness||readinessCache||{});
      const transfer=r.integrations&&r.integrations.providerTransfer?r.integrations.providerTransfer:{};
      const transferReady=transfer.enabled===true&&transfer.idrScaleVerified===true;
      if(provider){
        const providerStatus=String(provider.status||'unknown').toLowerCase();
        const apiHealthy=['ok','healthy','up','active','snapshot_ready'].includes(providerStatus);
        $('#masterProviderState').textContent=apiHealthy?(transferReady?'READY':'PARTIAL'):providerStatus.toUpperCase();
        $('#masterProviderMeta').textContent=`GoldslotPalase • ${Number(provider.gamesCount||0).toLocaleString('id-ID')} games • Wallet ${transferReady?'READY':'GATED'}`;
        $('#masterCatalogState').textContent=Number(provider.gamesCount||0).toLocaleString('id-ID');
        $('#masterCatalogMeta').textContent='Catalog games available';
      }
      if(r&&Object.keys(r).length){
        const config=Array.isArray(r.configuration)?r.configuration:[];
        const missing=config.filter(x=>!x.present).length;
        $('#masterSecurityState').textContent=missing===0?'READY':`${missing} CHECK`;
        $('#masterSecurityMeta').textContent=missing===0?'Required configuration present':'Configuration attention required';
      }
    }
    async function loadMasterControl(){
      if(!currentUser||!['admin','superadmin'].includes(currentRole))return;
      try{
        const [masterResult,providerResult,readinessResult]=await Promise.allSettled([api('master'),api('provider'),api('readiness')]);
        if(masterResult.status==='fulfilled')masterControlState=masterResult.value.control||masterResult.value;
        else throw masterResult.reason;
        const provider=providerResult.status==='fulfilled'?providerResult.value:null;
        const readinessEnvelope=readinessResult.status==='fulfilled'?readinessResult.value:null;
        const readiness=readinessEnvelope?(readinessEnvelope.readiness||readinessEnvelope):null;
        if(readiness)readinessCache=readiness;
        renderMasterControl(provider,readiness);
      }catch(err){toast('Master Control gagal dimuat: '+(err.message||'unknown'),'error')}
    }
    function masterPayload(){return {
      maintenanceMode:$('#masterMaintenance').value==='true',
      gameLaunchEnabled:$('#masterGameLaunch').value==='true',
      registrationEnabled:$('#masterRegistration').value==='true',
      promotionsEnabled:$('#masterPromotions').value==='true',
      memberWalletEnabled:$('#masterMemberWallet').value==='true',
      maintenanceMessage:$('#masterMessage').value.trim()
    }}
    $('#masterRefreshBtn').addEventListener('click',async()=>{busy(true);try{await loadMasterControl();toast('Master state diperbarui.','ok')}finally{busy(false)}});
    $('#masterSaveBtn').addEventListener('click',async()=>{
      const next=masterPayload();
      const critical=next.maintenanceMode===true||next.gameLaunchEnabled===false||next.memberWalletEnabled===false;
      if(critical&&!confirm('Perubahan ini dapat menghentikan akses game atau wallet member. Publish master state sekarang?'))return;
      busy(true);
      try{
        const d=await api('master',{method:'POST',body:{action:'update',expectedRevision:Number(masterControlState.revision||0),settings:next}});
        masterControlState=d.control||d;
        renderMasterControl();
        toast('Master Control berhasil dipublish ke backend.','ok');
        await loadMasterControl();
      }catch(err){
        if(err.message==='master_control_revision_conflict'){toast('Master state berubah di server. Refresh lalu ulangi.','error');await loadMasterControl()}
        else toast('Gagal publish Master Control: '+(err.message||'unknown'),'error');
      }finally{busy(false)}
    });

    /* DASHBOARD */
    let dashboardRange='7d';
    let memberCache=[];
    function renderDashboardChart(points=[]){
      const labels=$('#transactionChartLabels'),bars=$('#transactionChartBars');
      const fallback=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>({label:x,deposit:0,withdraw:0}));
      const data=(Array.isArray(points)&&points.length?points:fallback).slice(-7);
      const max=Math.max(1,...data.flatMap(x=>[Number(x.deposit||0),Number(x.withdraw||0)]));
      labels.innerHTML=data.map(x=>`<span>${escapeHtml(x.label||'—')}</span>`).join('');
      bars.innerHTML=data.map(x=>{const dh=Math.max(3,Math.round(Number(x.deposit||0)/max*100));const wh=Math.max(3,Math.round(Number(x.withdraw||0)/max*100));return `<div class="chart-day" title="${escapeHtml(x.label||'')}"><i class="chart-bar deposit" style="height:${dh}%"></i><i class="chart-bar withdraw" style="height:${wh}%"></i></div>`}).join('');
    }
    function renderDashboardActivity(items=[]){
      const root=$('#dashboardActivity');
      root.innerHTML=Array.isArray(items)&&items.length?items.slice(0,8).map(a=>`<div class="activity-item"><span class="activity-dot ${String(a.status||'').toLowerCase()==='ok'?'ok':''}"></span><span class="activity-main"><strong>${escapeHtml(a.title||a.action||'Activity')}</strong><span>${escapeHtml(a.description||a.resource||'Operational activity')}</span></span><span class="activity-time">${escapeHtml(a.timeLabel||'')}</span></div>`).join(''):`<div class="dashboard-empty">Belum ada activity feed.</div>`;
    }
    function updateDashboardMemberSnapshot(rows=[]){
      if(!$('#dashMemberLoaded'))return;
      $('#dashMemberLoaded').textContent=new Intl.NumberFormat('id-ID').format(rows.length);
      $('#dashMemberActive').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>String(r.status||'').toLowerCase()==='active').length);
      $('#dashMemberBlocked').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>String(r.status||'').toLowerCase()==='blocked').length);
      $('#dashMemberOnboarded').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>r.onboardingCompleted===true).length);
    }
    async function loadDashboardMemberSnapshot(){
      if(!canOpen('members')){updateDashboardMemberSnapshot([]);$('#dashOpenMembers')?.classList.add('hidden');return}
      $('#dashOpenMembers')?.classList.remove('hidden');
      try{const d=await api('members',{query:{limit:100}});updateDashboardMemberSnapshot(Array.isArray(d.items)?d.items:[])}catch{updateDashboardMemberSnapshot([])}
    }
    async function loadDashboard(){
      try{
        const d=await api('dashboard',{query:{range:dashboardRange}});
        const dep=d.depositToday==null?null:Number(d.depositToday),wd=d.withdrawToday==null?null:Number(d.withdrawToday);
        $('#metricMembers').textContent=Number.isFinite(Number(d.members))?new Intl.NumberFormat('id-ID').format(Number(d.members)):'—';
        $('#metricDeposits').textContent=d.depositToday!=null?fmtMoney(d.depositToday):'—';
        $('#metricWithdrawals').textContent=d.withdrawToday!=null?fmtMoney(d.withdrawToday):'—';
        $('#metricNetFlow').textContent=Number.isFinite(dep)&&Number.isFinite(wd)?fmtMoney(dep-wd):'—';
        $('#metricProvider').textContent='PROVIDER '+(d.providerHealth?String(d.providerHealth).toUpperCase():'—');
        $('#pendingDepositCount').textContent=d.pendingDeposits??'—';$('#pendingWithdrawCount').textContent=d.pendingWithdrawals??'—';$('#pendingReconCount').textContent=d.pendingReconciliation??'—';
        $('#metricMembersTrend').textContent=d.memberTrend!==undefined?String(d.memberTrend):'LIVE';$('#metricDepositsTrend').textContent=d.depositTrend!==undefined?String(d.depositTrend):'LIVE';$('#metricWithdrawalsTrend').textContent=d.withdrawTrend!==undefined?String(d.withdrawTrend):'LIVE';
        $('#chartPeriodLabel').textContent=dashboardRange==='1d'?'TODAY':dashboardRange==='30d'?'LAST 30 DAYS':'LAST 7 DAYS';
        renderDashboardChart(d.transactionTrend||d.chart||[]);renderDashboardActivity(d.activity||d.recentActivity||[]);
      }catch(err){renderDashboardChart([]);renderDashboardActivity([]);if(err.status!==404)toast('Dashboard live belum tersedia: '+err.message,'error')}
      await loadDashboardMemberSnapshot();
    }
    $('#dashboardRefresh').addEventListener('click',loadDashboard);
    $$('#dashboardRange [data-range]').forEach(b=>b.addEventListener('click',()=>{$$('#dashboardRange [data-range]').forEach(x=>x.classList.toggle('active',x===b));dashboardRange=b.dataset.range;loadDashboard()}));

    /* MEMBERS */
    function memberInitial(r){const source=(r.username||r.displayName||r.email||'M').trim();return escapeHtml((source[0]||'M').toUpperCase())}
    function memberDisplay(r){return r.username||r.displayName||r.email||r.uid||'Member'}
    function memberSecondary(r){return r.email||r.uid||'—'}
    function memberOnboardingBadge(r){return r.onboardingCompleted===true?`<span class="onboarding-state complete"><i></i> COMPLETE</span>`:`<span class="onboarding-state"><i></i> PENDING</span>`}
    function filterMemberRows(rows){const v=$('#memberOnboarding')?.value||'';if(v==='complete')return rows.filter(r=>r.onboardingCompleted===true);if(v==='pending')return rows.filter(r=>r.onboardingCompleted!==true);return rows}
    function updateMemberStats(rows){
      const wallet=rows.reduce((sum,r)=>sum+(Number.isFinite(Number(r.balance))?Number(r.balance):0),0);
      $('#memberStatLoaded').textContent=new Intl.NumberFormat('id-ID').format(rows.length);
      $('#memberStatActive').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>String(r.status||'').toLowerCase()==='active').length);
      $('#memberStatBlocked').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>String(r.status||'').toLowerCase()==='blocked').length);
      $('#memberStatOnboarded').textContent=new Intl.NumberFormat('id-ID').format(rows.filter(r=>r.onboardingCompleted===true).length);
      $('#memberStatWallet').textContent=fmtMoney(wallet);$('#memberResultText').textContent=`${rows.length} record ditampilkan • maksimum 100 record per request`;
    }
    function renderMemberDesktop(rows){const root=$('#membersTable');root.innerHTML=rows.length?rows.map(r=>`<tr><td><div class="member-identity"><span class="member-avatar">${memberInitial(r)}</span><span class="member-idcopy"><strong>${escapeHtml(memberDisplay(r))}</strong><span>${escapeHtml(memberSecondary(r))}</span></span></div></td><td>${stateChip(r.status)}</td><td><div class="money-stack"><strong>${fmtMoney(r.balance)}</strong><span>Total balance</span></div></td><td><div class="money-stack"><strong>${fmtMoney(r.availableBalance)}</strong><span>Available</span></div></td><td>${memberOnboardingBadge(r)}</td><td>${fmtDate(r.createdAt)}</td><td><button class="detail-btn" data-detail-type="Member" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`).join(''):`<tr class="empty-row"><td colspan="7">Tidak ada member yang cocok.</td></tr>`}
    function renderMemberMobile(rows){const root=$('#memberMobileList');root.innerHTML=rows.length?rows.map(r=>`<div class="member-mobile-card"><div class="member-mobile-head"><span class="member-avatar">${memberInitial(r)}</span><span class="member-idcopy"><strong>${escapeHtml(memberDisplay(r))}</strong><span>${escapeHtml(memberSecondary(r))}</span></span>${stateChip(r.status)}</div><div class="member-mobile-grid"><div class="member-mobile-kv"><span>Wallet</span><strong>${fmtMoney(r.balance)}</strong></div><div class="member-mobile-kv"><span>Available</span><strong>${fmtMoney(r.availableBalance)}</strong></div><div class="member-mobile-kv"><span>Onboarding</span><strong>${r.onboardingCompleted===true?'Complete':'Pending'}</strong></div><div class="member-mobile-kv"><span>Joined</span><strong>${fmtDate(r.createdAt)}</strong></div></div><div class="member-mobile-actions"><button class="detail-btn" data-detail-type="Member" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">View Detail</button></div></div>`).join(''):`<div class="dashboard-empty">Tidak ada member yang cocok.</div>`}
    function renderMembers(rows){memberCache=rows;updateMemberStats(rows);renderMemberDesktop(rows);renderMemberMobile(rows)}
    async function loadMembers(){
      $('#membersTable').innerHTML='<tr class="empty-row"><td colspan="7">Memuat member…</td></tr>';$('#memberMobileList').innerHTML='<div class="dashboard-empty">Memuat member…</div>';
      try{const d=await api('members',{query:{q:$('#memberSearch').value.trim(),status:$('#memberStatus').value,limit:100}});renderMembers(filterMemberRows(Array.isArray(d.items)?d.items:[]))}
      catch(err){renderMembers([]);$('#membersTable').innerHTML=`<tr class="empty-row"><td colspan="7">${escapeHtml(err.message)}</td></tr>`;$('#memberMobileList').innerHTML=`<div class="dashboard-empty">${escapeHtml(err.message)}</div>`}
    }
    $('#memberRefreshBtn').addEventListener('click',loadMembers);$('#memberApplyBtn').addEventListener('click',loadMembers);$('#memberStatus').addEventListener('change',loadMembers);$('#memberOnboarding').addEventListener('change',loadMembers);$('#memberSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();loadMembers()}});

    /* GENERIC LOADERS */
    const tableConfig={
      ledger:{target:'ledgerTable',cols:6,render:r=>`<tr><td>${fmtDate(r.createdAt)}</td><td>${escapeHtml(r.reference||'—')}</td><td>${escapeHtml(r.member||'—')}</td><td>${escapeHtml(r.type||'—')}</td><td>${fmtMoney(r.amount)}</td><td>${fmtMoney(r.balanceAfter)}</td></tr>`}
    };
    async function loadTable(name){
      const c=tableConfig[name];if(!c)return;
      const root=$('#'+c.target);root.innerHTML=`<tr class="empty-row"><td colspan="${c.cols}">Memuat data…</td></tr>`;
      try{
        const d=await api(name,{query:c.query?c.query():undefined});
        const rows=Array.isArray(d.items)?d.items:Array.isArray(d.rows)?d.rows:Array.isArray(d[name])?d[name]:[];
        root.innerHTML=rows.length?rows.map(c.render).join(''):`<tr class="empty-row"><td colspan="${c.cols}">Tidak ada data.</td></tr>`;
      }catch(err){
        root.innerHTML=`<tr class="empty-row"><td colspan="${c.cols}">${err.status===404?'Endpoint backend belum tersedia.':escapeHtml(err.message)}</td></tr>`;
      }
    }
    $$('[data-load]').forEach(b=>b.addEventListener('click',()=>{
      const n=b.dataset.load;
      if(n==='members')loadMembers();
      else if(n==='finance')loadFinanceSuite();
      else if(n==='deposits')loadDeposits();
      else if(n==='withdrawals')loadWithdrawals();
      else if(n==='reconciliation')loadReconciliation();
      else if(n==='ledger')loadLedger();
      else if(n==='catalog')loadCatalog();
      else if(n==='audit')loadAudit();
      else if(tableConfig[n])loadTable(n);
      else if(n==='provider'||n==='rtp')loadProvider();
      else if(n==='payment')loadPayment();
      else if(n==='website')loadWebsite();
      else if(n==='security'){loadReadiness(currentRole);renderSecurityCenter()}
      else if(n==='reports')toast('Pilih report yang ingin diekspor.');
    }));

    let ledgerCache=[],depositCache=[],withdrawCache=[],reconCache=[];
    function setSelectOptions(select,values,label){
      const current=select.value,unique=[...new Set(values.filter(Boolean).map(String))].sort();
      select.innerHTML=`<option value="">${label}</option>`+unique.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
      if(unique.includes(current))select.value=current;
    }
    function financeText(v){return String(v??'').toLowerCase()}
    function moneySum(rows){return rows.reduce((sum,r)=>sum+(Number.isFinite(Number(r.amount))?Number(r.amount):0),0)}
    function renderTxDesktop(root,rows,type){
      root.innerHTML=rows.length?rows.map(r=>{
        if(type==='deposit')return `<tr><td>${escapeHtml(r.reference||'—')}</td><td>${escapeHtml(r.member||r.username||'—')}</td><td>${escapeHtml(r.channel||'—')}</td><td>${fmtMoney(r.amount)}</td><td>${stateChip(r.status)}</td><td>${fmtDate(r.createdAt)}</td><td><button class="detail-btn" data-detail-type="Deposit" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`;
        if(type==='withdrawal')return `<tr><td>${escapeHtml(r.reference||'—')}</td><td>${escapeHtml(r.member||r.username||'—')}</td><td>${escapeHtml(r.destinationMasked||r.destination||'—')}</td><td>${fmtMoney(r.amount)}</td><td>${stateChip(r.status)}</td><td>${fmtDate(r.createdAt)}</td><td><button class="detail-btn" data-detail-type="Withdrawal" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`;
        return `<tr><td>${escapeHtml(r.reference||'—')}</td><td>${fmtMoney(r.internalAmount)}</td><td>${fmtMoney(r.externalAmount)}</td><td>${fmtMoney(r.difference)}</td><td>${stateChip(r.status)}</td><td>${fmtDate(r.updatedAt)}</td><td><button class="detail-btn" data-detail-type="Reconciliation" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`;
      }).join(''):`<tr class="empty-row"><td colspan="7">Tidak ada data.</td></tr>`;
    }
    function renderTxMobile(root,rows,type){
      root.innerHTML=rows.length?rows.map(r=>{
        const ref=r.reference||'—',member=r.member||r.username||'—';
