    /* GAME OPERATIONS */
    let catalogCache=[];
    let gameDisplayState={popular:[],newest:[],pinned:[],hiddenGames:[],providerOrder:[],hiddenProviders:[],revision:0,updatedAt:null};
    let gameDisplayDirty=false;
    function catalogStatus(r){return String(r.providerStatus||'unknown').toLowerCase()}
    function catalogGameKey(r){return `${Number(r.providerId)}::${String(r.code||'')}`}
    function normalizeDisplayState(raw){
      raw=raw&&typeof raw==='object'?raw:{};
      const list=(name)=>Array.isArray(raw[name])?[...new Set(raw[name].map(String))]:[];
      const ids=(name)=>Array.isArray(raw[name])?[...new Set(raw[name].map(Number).filter(Number.isSafeInteger))]:[];
      return {popular:list('popular'),newest:list('newest'),pinned:list('pinned'),hiddenGames:list('hiddenGames'),providerOrder:ids('providerOrder'),hiddenProviders:ids('hiddenProviders'),revision:Number.isSafeInteger(raw.revision)?raw.revision:0,updatedAt:raw.updatedAt||null};
    }
    function providerRows(){
      const map=new Map();catalogCache.forEach(r=>{const id=Number(r.providerId);if(Number.isSafeInteger(id)&&id>0&&!map.has(id))map.set(id,{providerId:id,providerName:r.providerName||`Provider ${id}`})});return [...map.values()];
    }
    function ensureProviderOrder(){
      const rows=providerRows(),valid=new Set(rows.map(r=>r.providerId));
      gameDisplayState.providerOrder=gameDisplayState.providerOrder.filter(id=>valid.has(id));
      rows.forEach(r=>{if(!gameDisplayState.providerOrder.includes(r.providerId))gameDisplayState.providerOrder.push(r.providerId)});
      gameDisplayState.hiddenProviders=gameDisplayState.hiddenProviders.filter(id=>valid.has(id));
    }
    function gameMemberVisible(r){return r.visible===true&&!gameDisplayState.hiddenGames.includes(catalogGameKey(r))&&!gameDisplayState.hiddenProviders.includes(Number(r.providerId))}
    const CATALOG_PAGE_SIZE=80;
    const DISPLAY_PAGE_SIZE=60;
    let catalogPage=0;
    let displayPage=0;
    function clampPage(page,total,size){const pages=Math.max(1,Math.ceil(total/size));return Math.max(0,Math.min(pages-1,page))}
    function updatePager(prefix,page,total,size){
      const pages=Math.max(1,Math.ceil(total/size)),safe=clampPage(page,total,size),start=total?safe*size+1:0,end=Math.min(total,(safe+1)*size);
      const state=$('#'+prefix+'PageState');if(state)state.textContent=total?`${start}–${end} dari ${total} game`:'0 game';
      const prev=$('#'+prefix+'PrevBtn'),next=$('#'+prefix+'NextBtn');if(prev)prev.disabled=safe<=0;if(next)next.disabled=safe>=pages-1;
      return safe;
    }
    function filterCatalog(){
      const q=financeText($('#catalogSearch').value),status=$('#catalogStatus').value,category=$('#catalogCategory').value;
      return catalogCache.filter(r=>(!q||[r.name,r.code].some(v=>financeText(v).includes(q)))&&(!status||catalogStatus(r)===status)&&(!category||String(r.category||'')===category));
    }
    function renderCatalog(){
      const rows=filterCatalog();
      catalogPage=updatePager('catalog',catalogPage,rows.length,CATALOG_PAGE_SIZE);
      const visibleRows=rows.slice(catalogPage*CATALOG_PAGE_SIZE,(catalogPage+1)*CATALOG_PAGE_SIZE);
      const active=rows.filter(r=>catalogStatus(r)==='active').length,disabled=rows.filter(r=>catalogStatus(r)==='disabled').length,categories=new Set(rows.map(r=>r.category).filter(Boolean)).size;
      $('#catalogStatLoaded').textContent=rows.length;$('#catalogStatActive').textContent=active;$('#catalogStatDisabled').textContent=disabled;$('#catalogStatCategories').textContent=categories;
      $('#catalogResultText').textContent=`${rows.length} game cocok • menampilkan maksimal ${CATALOG_PAGE_SIZE} per halaman • GoldslotPalase`;
      $('#catalogTable').innerHTML=visibleRows.length?visibleRows.map(r=>`<tr><td>${escapeHtml(r.name||'—')}</td><td>${escapeHtml(r.code||'—')}</td><td>${escapeHtml(r.category||'—')}</td><td>${stateChip(r.providerStatus)}</td><td>${stateChip(gameMemberVisible(r)?'active':'disabled')}</td><td>${fmtDate(r.updatedAt)}</td><td><button class="detail-btn" data-detail-type="Game" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`).join(''):`<tr class="empty-row"><td colspan="7">Tidak ada game yang cocok.</td></tr>`;
      $('#catalogMobileList').innerHTML=visibleRows.length?visibleRows.map(r=>`<div class="game-mobile-card"><div class="game-mobile-head"><span class="game-mobile-icon">G</span><span class="game-mobile-copy"><strong>${escapeHtml(r.name||'Game')}</strong><span>${escapeHtml(r.code||'—')}</span></span>${stateChip(r.providerStatus)}</div><div class="game-mobile-grid"><div class="game-mobile-kv"><span>Category</span><strong>${escapeHtml(r.category||'—')}</strong></div><div class="game-mobile-kv"><span>Member</span><strong>${gameMemberVisible(r)?'Tampil':'Disembunyikan'}</strong></div><div class="game-mobile-kv"><span>Provider</span><strong>${escapeHtml(r.providerName||'GoldslotPalase')}</strong></div><div class="game-mobile-kv"><span>Updated</span><strong>${fmtDate(r.updatedAt)}</strong></div></div><div class="game-mobile-actions"><button class="detail-btn" data-detail-type="Game" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">View Detail</button></div></div>`).join(''):`<div class="dashboard-empty">Tidak ada game yang cocok.</div>`;
    }
    function gameByKey(key){return catalogCache.find(r=>catalogGameKey(r)===key)}
    function displayListItem(key,section){
      const game=gameByKey(key);if(!game)return '';
      return `<div class="curation-item"><span><strong>${escapeHtml(game.name||game.code)}</strong><span>${escapeHtml(game.providerName||'Provider')}</span></span><span class="curation-move"><button type="button" data-order-section="${section}" data-order-key="${encodeURIComponent(key)}" data-order-dir="-1" aria-label="Naik">↑</button><button type="button" data-order-section="${section}" data-order-key="${encodeURIComponent(key)}" data-order-dir="1" aria-label="Turun">↓</button></span></div>`;
    }
    function renderOrderedSection(section,target,countId,max){
      const values=gameDisplayState[section].filter(key=>gameByKey(key));gameDisplayState[section]=values;
      $('#'+countId).textContent=`${values.length} / ${max}`;
      $('#'+target).innerHTML=values.length?values.map(key=>displayListItem(key,section)).join(''):`<div class="curation-empty">Belum ada pilihan.</div>`;
    }
    function renderMemberDisplayList(){
      const q=financeText($('#displayGameSearch').value);
      const rows=catalogCache.filter(r=>!q||[r.name,r.code,r.providerName].some(v=>financeText(v).includes(q)));
      displayPage=updatePager('display',displayPage,rows.length,DISPLAY_PAGE_SIZE);
      const visibleRows=rows.slice(displayPage*DISPLAY_PAGE_SIZE,(displayPage+1)*DISPLAY_PAGE_SIZE);
      $('#memberDisplayList').innerHTML=visibleRows.length?visibleRows.map(r=>{const key=catalogGameKey(r),hidden=gameDisplayState.hiddenGames.includes(key),popular=gameDisplayState.popular.includes(key),newest=gameDisplayState.newest.includes(key),pinned=gameDisplayState.pinned.includes(key);return `<div class="display-game-row"><div class="display-game-main"><span class="display-game-thumb">${r.imageUrl?`<img alt="" loading="lazy" decoding="async" src="${escapeHtml(r.imageUrl)}"/>`:'GAME'}</span><span class="display-game-copy"><strong>${escapeHtml(r.name||r.code)}</strong><span>${escapeHtml(r.providerName||'Provider')} • ${escapeHtml(r.code||'')}</span></span></div><div class="display-game-actions"><button class="catalog-toggle ${!hidden?'on':''}" data-display-toggle="visible" data-game-key="${encodeURIComponent(key)}" type="button">Tampil</button><button class="catalog-toggle ${popular?'on':''}" data-display-toggle="popular" data-game-key="${encodeURIComponent(key)}" type="button">Populer</button><button class="catalog-toggle ${newest?'on':''}" data-display-toggle="newest" data-game-key="${encodeURIComponent(key)}" type="button">Terbaru</button><button class="catalog-toggle warn ${pinned?'on':''}" data-display-toggle="pinned" data-game-key="${encodeURIComponent(key)}" type="button">Paling Atas</button></div></div>`}).join(''):`<div class="dashboard-empty">Game tidak ditemukan.</div>`;
    }
    function renderProviderOrder(){
      ensureProviderOrder();const byId=new Map(providerRows().map(r=>[r.providerId,r]));
      $('#providerOrderList').innerHTML=gameDisplayState.providerOrder.length?gameDisplayState.providerOrder.map((id,index)=>{const p=byId.get(id);if(!p)return '';const hidden=gameDisplayState.hiddenProviders.includes(id);return `<div class="provider-order-row"><div class="provider-order-main"><span class="game-mobile-icon">${index+1}</span><span class="provider-order-copy"><strong>${escapeHtml(p.providerName)}</strong><span>Provider ID ${id} • posisi ${index+1}</span></span></div><div class="provider-order-actions"><button class="catalog-toggle ${!hidden?'on':''}" data-provider-visible="${id}" type="button">Tampil</button><button class="provider-position" data-provider-move="${id}" data-provider-dir="-1" type="button" aria-label="Naik">↑</button><button class="provider-position" data-provider-move="${id}" data-provider-dir="1" type="button" aria-label="Turun">↓</button></div></div>`}).join(''):`<div class="dashboard-empty">Provider belum tersedia.</div>`;
    }
    function renderGameDisplay(){
      ensureProviderOrder();
      renderOrderedSection('popular','popularOrderList','popularCount',24);renderOrderedSection('newest','newestOrderList','newestCount',24);renderOrderedSection('pinned','pinnedOrderList','pinnedCount',60);
      renderMemberDisplayList();renderProviderOrder();
      $('#displayRevision').textContent=`REV ${gameDisplayState.revision}`;
      ['gameDisplayDirty','providerDisplayDirty'].forEach(id=>{const el=$('#'+id);if(el){el.textContent=gameDisplayDirty?'UNSAVED':'SAVED';el.className='catalog-dirty'+(gameDisplayDirty?' changed':'')}});
    }
    function markDisplayDirty(){gameDisplayDirty=true;renderGameDisplay();renderCatalog()}
    function toggleArrayValue(section,key,max){const list=gameDisplayState[section],index=list.indexOf(key);if(index>=0)list.splice(index,1);else if(list.length<max)list.push(key);else{toast(`Batas ${max} game untuk bagian ini.`,'error');return false}return true}
    function moveArrayValue(section,key,dir){const list=gameDisplayState[section],index=list.indexOf(key);if(index<0)return;const next=Math.max(0,Math.min(list.length-1,index+dir));if(next===index)return;list.splice(index,1);list.splice(next,0,key);markDisplayDirty()}
    async function saveGameDisplay(){
      const buttons=[$('#gameDisplaySaveBtn'),$('#providerOrderSaveBtn')].filter(Boolean);buttons.forEach(b=>b.disabled=true);busy(true);
      try{
        ensureProviderOrder();
        const d=await api('catalog',{method:'POST',body:{action:'update',expectedRevision:gameDisplayState.revision,settings:{popular:gameDisplayState.popular,newest:gameDisplayState.newest,pinned:gameDisplayState.pinned,hiddenGames:gameDisplayState.hiddenGames,providerOrder:gameDisplayState.providerOrder,hiddenProviders:gameDisplayState.hiddenProviders}}});
        gameDisplayState=normalizeDisplayState(d.display);gameDisplayDirty=false;renderGameDisplay();renderCatalog();
        const currentCache=readCatalogLocalCache();if(currentCache?.payload)writeCatalogLocalCache({...currentCache.payload,display:d.display});
        toast('Pengaturan game member berhasil disimpan.','ok');
      }catch(err){toast(err.message==='game_display_revision_conflict'?'Pengaturan berubah di server. Refresh Catalog lalu ulangi perubahan.':'Gagal menyimpan pengaturan game: '+err.message,'error')}
      finally{buttons.forEach(b=>b.disabled=false);busy(false)}
    }
    function setCatalogPane(name){$$('.catalog-admin-tab').forEach(b=>b.classList.toggle('active',b.dataset.catalogPane===name));$$('[data-catalog-pane-content]').forEach(p=>p.classList.toggle('active',p.dataset.catalogPaneContent===name))}
    const CATALOG_LOCAL_CACHE_KEY='brandalbet.backoffice.catalog.v2';
    const CATALOG_LOCAL_FRESH_MS=5*60*1000;
    const CATALOG_LOCAL_STALE_MS=24*60*60*1000;
    let catalogLoadPromise=null;
    function readCatalogLocalCache(){
      try{
        const raw=localStorage.getItem(CATALOG_LOCAL_CACHE_KEY);if(!raw)return null;
        const parsed=JSON.parse(raw),savedAt=Number(parsed?.savedAt||0),age=Math.max(0,Date.now()-savedAt);
        if(!parsed?.payload||!savedAt||age>CATALOG_LOCAL_STALE_MS)return null;
        return {payload:parsed.payload,age,fresh:age<=CATALOG_LOCAL_FRESH_MS};
      }catch(_e){return null}
    }
    function writeCatalogLocalCache(payload){try{localStorage.setItem(CATALOG_LOCAL_CACHE_KEY,JSON.stringify({savedAt:Date.now(),payload}))}catch(_e){}}
    function applyCatalogPayload(d,{cached=false}={}){
      catalogCache=Array.isArray(d?.items)?d.items:[];gameDisplayState=normalizeDisplayState(d?.display);gameDisplayDirty=false;ensureProviderOrder();
      setSelectOptions($('#catalogCategory'),catalogCache.map(r=>r.category),'All category');renderCatalog();renderGameDisplay();
      const source=$('#catalogSourceState');if(source){source.textContent=cached?'BROWSER CACHE • SNAPSHOT':'SERVER SNAPSHOT • GOLDSLOTPALASE';source.className=cached?'':'ok'}
    }
    async function loadCatalog(force=false){
      const cached=readCatalogLocalCache();
      if(cached)applyCatalogPayload(cached.payload,{cached:true});
      if(cached?.fresh&&!force)return true;
      if(catalogLoadPromise&&!force)return catalogLoadPromise;
      if(!cached){$('#catalogTable').innerHTML='<tr class="empty-row"><td colspan="7">Memuat catalog…</td></tr>';$('#catalogMobileList').innerHTML='<div class="dashboard-empty">Menghubungkan catalog GoldslotPalase…</div>';}
      if(cached&&!force)await new Promise(resolve=>setTimeout(resolve,180));
      catalogLoadPromise=(async()=>{
        try{
          const d=await api('catalog',{query:{limit:200}});
          applyCatalogPayload(d);writeCatalogLocalCache(d);return true;
        }catch(err){
          if(!cached){catalogCache=[];renderCatalog();renderGameDisplay();toast('Catalog gagal dimuat: '+err.message,'error')}
          else toast('Menggunakan cache katalog. Refresh manual jika ingin mengambil data terbaru.');
          return !!cached;
        }finally{catalogLoadPromise=null}
      })();
      return catalogLoadPromise;
    }
    $$('.catalog-admin-tab').forEach(b=>b.addEventListener('click',()=>setCatalogPane(b.dataset.catalogPane)));
    $$('[data-open-catalog-pane]').forEach(b=>b.addEventListener('click',()=>{setCatalogPane(b.dataset.openCatalogPane);document.querySelector('[data-screen="catalog"]')?.scrollIntoView({block:'start'})}));
    $('#catalogRefreshBtn').addEventListener('click',()=>loadCatalog(true));
    $('#catalogSyncBtn').addEventListener('click',async()=>{
      if(!['admin','superadmin'].includes(currentRole))return toast('Hanya admin/superadmin yang dapat melakukan sync provider.','error');
      if(!confirm('Sync Goldslot akan memanggil API katalog provider dan mengganti snapshot server. Lanjutkan?'))return;
      busy(true);$('#catalogSyncBtn').disabled=true;
      try{const d=await api('catalog',{method:'POST',body:{action:'sync'}});applyCatalogPayload(d);writeCatalogLocalCache(d);toast('Snapshot Goldslot berhasil diperbarui.','ok')}
      catch(err){toast('Sync Goldslot gagal: '+err.message,'error')}
      finally{$('#catalogSyncBtn').disabled=false;busy(false)}
    });
    $('#catalogResetFilterBtn').addEventListener('click',()=>{$('#catalogSearch').value='';$('#catalogStatus').value='';$('#catalogCategory').value='';catalogPage=0;renderCatalog()});
    $('#catalogStatus').addEventListener('change',()=>{catalogPage=0;renderCatalog()});$('#catalogCategory').addEventListener('change',()=>{catalogPage=0;renderCatalog()});
    let catalogSearchTimer=null;$('#catalogSearch').addEventListener('input',()=>{clearTimeout(catalogSearchTimer);catalogSearchTimer=setTimeout(()=>{catalogPage=0;renderCatalog()},120)});
    let displaySearchTimer=null;$('#displayGameSearch').addEventListener('input',()=>{clearTimeout(displaySearchTimer);displaySearchTimer=setTimeout(()=>{displayPage=0;renderMemberDisplayList()},120)});
    $('#catalogPrevBtn').addEventListener('click',()=>{catalogPage=Math.max(0,catalogPage-1);renderCatalog();document.querySelector('[data-catalog-pane-content="catalog-list"]')?.scrollIntoView({block:'start',behavior:'smooth'})});
    $('#catalogNextBtn').addEventListener('click',()=>{catalogPage++;renderCatalog();document.querySelector('[data-catalog-pane-content="catalog-list"]')?.scrollIntoView({block:'start',behavior:'smooth'})});
    $('#displayPrevBtn').addEventListener('click',()=>{displayPage=Math.max(0,displayPage-1);renderMemberDisplayList();document.querySelector('[data-catalog-pane-content="member-display"]')?.scrollIntoView({block:'start',behavior:'smooth'})});
    $('#displayNextBtn').addEventListener('click',()=>{displayPage++;renderMemberDisplayList();document.querySelector('[data-catalog-pane-content="member-display"]')?.scrollIntoView({block:'start',behavior:'smooth'})});
    $('#memberDisplayList').addEventListener('click',e=>{const b=e.target.closest('[data-display-toggle]');if(!b)return;const key=decodeURIComponent(b.dataset.gameKey||''),type=b.dataset.displayToggle;if(type==='visible'){const i=gameDisplayState.hiddenGames.indexOf(key);if(i>=0)gameDisplayState.hiddenGames.splice(i,1);else gameDisplayState.hiddenGames.push(key);markDisplayDirty();return}const max=type==='pinned'?60:24;if(toggleArrayValue(type,key,max))markDisplayDirty()});
    ['popularOrderList','newestOrderList','pinnedOrderList'].forEach(id=>$('#'+id).addEventListener('click',e=>{const b=e.target.closest('[data-order-section]');if(!b)return;moveArrayValue(b.dataset.orderSection,decodeURIComponent(b.dataset.orderKey||''),Number(b.dataset.orderDir||0))}));
    $('#providerOrderList').addEventListener('click',e=>{const visible=e.target.closest('[data-provider-visible]');if(visible){const id=Number(visible.dataset.providerVisible),i=gameDisplayState.hiddenProviders.indexOf(id);if(i>=0)gameDisplayState.hiddenProviders.splice(i,1);else gameDisplayState.hiddenProviders.push(id);markDisplayDirty();return}const move=e.target.closest('[data-provider-move]');if(!move)return;const id=Number(move.dataset.providerMove),index=gameDisplayState.providerOrder.indexOf(id),next=Math.max(0,Math.min(gameDisplayState.providerOrder.length-1,index+Number(move.dataset.providerDir||0)));if(index>=0&&next!==index){gameDisplayState.providerOrder.splice(index,1);gameDisplayState.providerOrder.splice(next,0,id);markDisplayDirty()}});
    $('#gameDisplaySaveBtn').addEventListener('click',saveGameDisplay);$('#providerOrderSaveBtn').addEventListener('click',saveGameDisplay);

    let providerLastLoadedAt=0;
    const PROVIDER_UI_CACHE_TTL_MS=300000;

    const capabilityLabels={
      catalog:['Game Catalog','Katalog game provider tersedia melalui backend.'],
      launch:['Game Launch','Backend melaporkan game launch capability.'],
      walletTransfer:['Wallet Transfer','Transfer wallet hanya aktif bila environment provider tervalidasi.'],
      balanceReconciliation:['Balance Reconciliation','Rekonsiliasi saldo provider mengikuti gate backend.'],
      transactionHistory:['Transaction History','Riwayat transaksi provider tersedia melalui backend.'],
      transactionIncrementalSync:['Transaction Sync','Incremental sync hanya aktif bila gate backend diaktifkan.'],
      rewardPayout:['Reward Payout','Payout cashback/referral hanya aktif bila source settlement tervalidasi.'],
      rtpGlobal:['Global RTP','Capability global RTP resmi provider.'],
      rtpPerGame:['Per Game RTP','Capability RTP per game resmi provider.'],
      rtpPerUser:['Per User RTP','Capability RTP per user resmi provider.'],
      scatterControl:['Scatter Control','Capability scatter control resmi provider.']
    };
    function capState(value){return value?'<span class="mini-state ok">SUPPORTED</span>':'<span class="mini-state warn">NOT AVAILABLE</span>'}
    function renderCapabilities(){
      const root=$('#providerCapabilityList'),keys=Object.keys(capabilityLabels);
      root.innerHTML=keys.map(key=>{const [label,desc]=capabilityLabels[key],value=providerCapabilities[key]===true;return `<div class="cap-card"><div class="cap-top"><strong>${escapeHtml(label)}</strong>${capState(value)}</div><p>${escapeHtml(desc)}</p></div>`}).join('');
    }
    function renderRtpGates(){
      const map=[['rtpGlobal','rtpGlobalState'],['rtpPerGame','rtpGameState'],['rtpPerUser','rtpUserState'],['scatterControl','scatterState']];
      map.forEach(([key,id])=>{const el=$('#'+id),yes=providerCapabilities[key]===true;el.textContent=yes?'CAPABILITY':'UNAVAILABLE';el.className='mini-state '+(yes?'ok':'warn')});
      ['rtpGlobalEndpoint','rtpGameEndpoint','rtpUserEndpoint','scatterEndpoint'].forEach(id=>{$('#'+id).textContent='NOT CONNECTED'});
    }
    function renderProviderHealth(d){
      const status=String(d.status||'unknown').toUpperCase(),wallet=providerCapabilities.walletTransfer===true,recon=providerCapabilities.balanceReconciliation===true;
      $('#healthApi').textContent=status;$('#healthCatalogGames').textContent=d.gamesCount??'—';$('#healthWalletTransfer').textContent=wallet?'SUPPORTED':'GATED';$('#healthLastCheck').textContent=d.lastSync?fmtDate(d.lastSync):'—';
      $('#healthTransferState').textContent=wallet?'READY':'GATED';$('#healthTransferState').className='mini-state '+(wallet?'ok':'warn');
      $('#healthReconState').textContent=recon?'READY':'GATED';$('#healthReconState').className='mini-state '+(recon?'ok':'warn');
      const timeline=[
        {title:d.liveChecked===true?'Provider Live API':'Stored Snapshot',text:d.message||'Provider state received.',ok:d.liveChecked===true?['ok','healthy','up','active'].includes(String(d.status||'').toLowerCase()):['snapshot_ready','snapshot_stale'].includes(String(d.status||'').toLowerCase())},
        {title:'Catalog',text:`${d.gamesCount??0} games reported by backend.`,ok:true},
        {title:'Wallet Transfer',text:wallet?'Capability enabled by backend gates.':'Capability remains fail-closed.',ok:wallet},
        {title:'Balance Reconciliation',text:recon?'Capability enabled by backend gates.':'Capability remains fail-closed.',ok:recon}
      ];
      $('#providerHealthTimeline').innerHTML=timeline.map(x=>`<div class="health-event"><i class="health-dot ${x.ok?'ok':''}"></i><span><strong>${escapeHtml(x.title)}</strong><span>${escapeHtml(x.text)}</span></span><time>${d.lastSync?escapeHtml(fmtDate(d.lastSync)):'—'}</time></div>`).join('');
    }
    async function loadProvider(force=false){
      if(!force&&providerLastLoadedAt&&Date.now()-providerLastLoadedAt<PROVIDER_UI_CACHE_TTL_MS&&Object.keys(providerCapabilities).length)return;
      try{
        const d=await api('provider');
        providerCapabilities=d.capabilities||{};
        const healthy=['ok','healthy','up','active','snapshot_ready'].includes(String(d.status||'').toLowerCase());
        $('#providerConnection').textContent=String(d.status||'—').toUpperCase();
        $('#providerGames').textContent=d.gamesCount??'—';
        $('#providerLastSync').textContent=d.lastSync?fmtDate(d.lastSync):'—';
        $('#providerMessage').textContent=d.message||'Provider status diterima dari backend.';
        $('#providerStatusBadge').textContent=String(d.status||'UNKNOWN').toUpperCase();$('#providerStatusBadge').className='mini-state '+(healthy?'ok':'warn');
        $('#metricProvider').textContent='PROVIDER '+String(d.status||'—').toUpperCase();
        $('#providerText').textContent=d.message||'Provider status diterima dari backend.';
        $('#providerState').textContent=String(d.status||'UNKNOWN').toUpperCase();$('#providerState').className='mini-state '+(healthy?'ok':'warn');
        providerLastLoadedAt=Date.now();renderCapabilities();renderRtpGates();renderProviderHealth(d);if($('#providerSyncTx'))$('#providerSyncTx').disabled=providerCapabilities.transactionIncrementalSync!==true;
      }catch(err){
        $('#providerMessage').textContent='Provider check gagal: '+err.message;$('#providerStatusBadge').textContent='UNAVAILABLE';$('#providerStatusBadge').className='mini-state warn';
        $('#providerText').textContent='Provider check gagal: '+err.message;$('#providerState').textContent='UNAVAILABLE';$('#providerState').className='mini-state warn';
        providerCapabilities={};renderCapabilities();renderRtpGates();
        $('#healthApi').textContent='UNAVAILABLE';$('#healthCatalogGames').textContent='—';$('#healthWalletTransfer').textContent='—';$('#healthLastCheck').textContent='—';
        $('#providerHealthTimeline').innerHTML='<div class="dashboard-empty">Provider health tidak tersedia.</div>';
      }
    }
    async function refreshGameOperations(){
      busy(true);try{await Promise.all([loadProvider(),loadCatalog()]);toast('Game Operations diperbarui.','ok')}finally{busy(false)}
    }
    $('#providerRefreshBtn').addEventListener('click',()=>loadProvider(true));
    $('#providerServerCheck').addEventListener('click',async()=>{
      if(!['admin','superadmin'].includes(currentRole))return toast('Live provider check hanya untuk admin/superadmin.','error');
      if(!confirm('Live API Check akan melakukan satu panggilan langsung ke GoldslotPalase. Lanjutkan?'))return;
      busy(true);try{const d=await api('provider',{method:'POST',body:{action:'check'}});providerCapabilities=d.capabilities||{};providerLastLoadedAt=Date.now();renderCapabilities();renderRtpGates();renderProviderHealth(d);$('#providerConnection').textContent=String(d.status||'—').toUpperCase();$('#providerStatusBadge').textContent=String(d.status||'UNKNOWN').toUpperCase();$('#providerStatusBadge').className='mini-state ok';$('#providerMessage').textContent=d.message||'Live check selesai.';toast('Live provider check berhasil.','ok')}catch(err){toast('Live provider check gagal: '+err.message,'error')}finally{busy(false)}
    });
    $('#providerSyncTx').addEventListener('click',async()=>{
      if(!['admin','superadmin'].includes(currentRole))return toast('Sync transaksi hanya untuk admin/superadmin.','error');
      if(providerCapabilities.transactionIncrementalSync!==true)return toast('Transaction sync masih digate di backend.','error');
      if(!confirm('Sync Transactions akan meminta settlement provider terbaru. Lanjutkan?'))return;
      busy(true);try{const d=await api('provider',{method:'POST',body:{action:'sync-transactions'}});toast('Transaction sync selesai: '+String(d?.transactions?.status||'OK'),'ok');await loadProvider(true);if(canOpen('rewards'))await loadRewards()}catch(err){toast('Transaction sync gagal: '+err.message,'error')}finally{busy(false)}
    });
    $('#providerOpenCatalog').addEventListener('click',()=>openScreen('catalog'));
    $('#rtpRefreshBtn').addEventListener('click',()=>loadProvider(true));$('#healthRefreshBtn').addEventListener('click',()=>loadProvider(true));

    /* REWARDS / REFERRAL / CASHBACK */
    let rewardOverviewCache={};
    function rewardPct(bps){const n=Number(bps);return Number.isFinite(n)?(n/100).toLocaleString('id-ID',{maximumFractionDigits:2})+'%':'—'}
    function rewardGate(id,on,onText='READY',offText='GATED'){const el=$('#'+id);if(!el)return;el.textContent=on?onText:offText;el.className='mini-state '+(on?'ok':'warn')}
    function renderRewards(payload){
      const r=payload?.rewards||payload||{},p=r.policy||{},w=r.week||{},f=r.finalization||{},source=r.source||{},integrity=r.integrity||{};
      rewardOverviewCache=r;
      $('#rewardEngineState').textContent='API CONNECTED';$('#rewardEngineState').className='chip green';
      $('#rewardCashbackRate').textContent=rewardPct(p.cashbackRateBps)+' · MIN '+fmtMoney(p.cashbackMinimumNetLossMinor);
      $('#rewardReferralRate').textContent=rewardPct(p.referralRateBps);
      $('#rewardTurnover').textContent=Number.isFinite(Number(p.cashbackTurnoverMultiplier))?String(p.cashbackTurnoverMultiplier)+'×':'—';
      $('#rewardWeekState').textContent=w.weekKey||'—';$('#rewardWeekState').className='mini-state '+(f.status==='complete'?'ok':'warn');
      if(w.weekKey&&!$('#rewardWeekInput').value)$('#rewardWeekInput').value=w.weekKey;
      $('#rewardFinalStatus').textContent=String(f.status||'unknown').toUpperCase();$('#rewardFinalStatus').className='mini-state '+(f.status==='complete'?'ok':'warn');
      $('#rewardWeekWindow').textContent=(w.startAt&&w.endAt)?fmtDate(w.startAt)+' — '+fmtDate(w.endAt):'—';
      $('#rewardProcessed').textContent=Number(f.processedCount||0).toLocaleString('id-ID');
      $('#rewardCashbackTotal').textContent=fmtMoney(f.cashbackMinor||0);$('#rewardCashbackCount').textContent=Number(f.cashbackCount||0).toLocaleString('id-ID')+' payout';
      $('#rewardReferralTotal').textContent=fmtMoney(f.referralMinor||0);$('#rewardReferralCount').textContent=Number(f.referralCount||0).toLocaleString('id-ID')+' payout';
      rewardGate('rewardSourceState',r.transactionSyncEnabled===true,'ENABLED','DISABLED');
      rewardGate('rewardPayoutState',r.payoutEnabled===true,'ENABLED','DISABLED');
      rewardGate('rewardVerifiedState',r.sourceReady===true,'VERIFIED','NOT READY');
      const integrityOk=String(integrity.status||'clear').toLowerCase()!=='blocked';rewardGate('rewardIntegrityState',integrityOk,'CLEAR','BLOCKED');
      $('#rewardSourceMeta').textContent='Source: '+String(source.status||'not_initialized')+(r.pendingClosedWeekRound?' · pending closed-week round':'')+(r.sourceReadyAfter?' · required after '+fmtDate(r.sourceReadyAfter):'');
      const canFinalize=r.payoutEnabled===true&&r.transactionSyncEnabled===true&&r.sourceReady===true&&integrityOk&&f.status!=='complete';
      $('#rewardFinalizeBtn').disabled=!canFinalize;
      $('#rewardNotice').textContent=canFinalize?'Verified source is ready. Finalization may proceed with backend idempotency.':'Reward API is connected, but payout remains fail-closed until transaction source, payout, and integrity gates are all ready.';
    }
    async function loadRewards(){
      const input=$('#rewardWeekInput'),week=input?.value||'';
      try{const d=await api('rewards',{query:week?{week}:{}});renderRewards(d)}
      catch(err){$('#rewardEngineState').textContent='UNAVAILABLE';$('#rewardEngineState').className='chip red';$('#rewardNotice').textContent='Reward status gagal dimuat: '+err.message;$('#rewardFinalizeBtn').disabled=true}
    }
    async function finalizeRewardWeek(){
      const weekKey=$('#rewardWeekInput').value||rewardOverviewCache?.week?.weekKey;if(!weekKey)return toast('Pilih week key hari Senin.','error');
      if(!confirm('Finalize reward week '+weekKey+'? Backend akan menolak bila settlement source atau production gate belum siap.'))return;
      busy(true);$('#rewardFinalizeBtn').disabled=true;
      try{const d=await api('rewards',{method:'POST',body:{action:'finalize-week',weekKey}});toast('Finalization: '+String(d?.finalization?.status||'processed'),'ok');await loadRewards()}
      catch(err){const map={reward_payout_disabled:'Reward payout masih dinonaktifkan di backend.',reward_source_disabled:'Provider transaction sync masih dinonaktifkan.',reward_source_not_ready:'Settlement source belum siap untuk minggu tersebut.',reward_rounds_not_finalized:'Masih ada provider round yang belum final.',reward_week_integrity_blocked:'Integrity gate memblokir settlement.'};toast(map[err.message]||('Finalization ditolak: '+err.message),'error');await loadRewards()}
      finally{busy(false)}
    }
    async function issueReferralCode(){
      if(!['admin','superadmin'].includes(currentRole))return toast('Hanya admin/superadmin yang dapat menerbitkan referral code.','error');
      const targetUid=$('#rewardTargetUid').value.trim(),code=$('#rewardCode').value.trim().toUpperCase();if(!targetUid)return toast('Promoter Member UID wajib diisi.','error');
      busy(true);$('#rewardIssueCodeBtn').disabled=true;
      try{const d=await api('rewards',{method:'POST',body:{action:'issue-referral-code',targetUid,...(code?{code}:{})}});$('#rewardReferralResult').textContent='Issued: '+String(d?.referral?.code||'—')+' · promoter '+String(d?.referral?.promoterUid||targetUid);$('#rewardCode').value='';toast('Referral code berhasil diterbitkan.','ok')}
      catch(err){toast('Referral code gagal: '+err.message,'error')}
      finally{$('#rewardIssueCodeBtn').disabled=false;busy(false)}
    }
    $('#rewardRefreshBtn').addEventListener('click',loadRewards);$('#rewardWeekInput').addEventListener('change',loadRewards);$('#rewardFinalizeBtn').addEventListener('click',finalizeRewardWeek);$('#rewardIssueCodeBtn').addEventListener('click',issueReferralCode);

    /* PROMOTIONS */
    function localValue(iso){if(!iso)return '';const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
    function isoValue(v){if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString()}
    function promoSections(){return [{title:'Mekanisme',body:$('#promoMechanism').value.trim()},{title:'Syarat & Ketentuan',body:$('#promoTerms').value.trim()},{title:'Keterangan',body:$('#promoNote').value.trim()}].filter(x=>x.body)}
    function promoPayload(){return {id:$('#promoId').value.trim()||undefined,title:$('#promoTitle').value.trim(),category:$('#promoCategory').value,badge:$('#promoBadge').value.trim(),active:$('#promoActive').value==='true',summary:$('#promoSummary').value.trim(),imageUrl:$('#promoImageUrl').value.trim(),startAt:isoValue($('#promoStartAt').value),endAt:isoValue($('#promoEndAt').value),sortOrder:Number($('#promoSortOrder').value||100),ctaLabel:$('#promoCtaLabel').value.trim()||'Lanjutkan',ctaRoute:$('#promoCtaRoute').value,detailIntro:$('#promoDetailIntro').value.trim(),sections:promoSections()}}
    function promoRuntimeState(p,now=Date.now()){if(p.active===false)return 'inactive';const start=p.startAt?Date.parse(p.startAt):null,end=p.endAt?Date.parse(p.endAt):null;if(Number.isFinite(start)&&start>now)return 'scheduled';if(Number.isFinite(end)&&end<now)return 'inactive';return 'live'}
    function promoStateChip(state){return state==='live'?'<span class="chip green">LIVE</span>':state==='scheduled'?'<span class="chip gold">SCHEDULED</span>':'<span class="chip">INACTIVE</span>'}
    function updatePromoStats(){const states=promoCache.map(p=>promoRuntimeState(p));$('#promoStatTotal').textContent=promoCache.length;$('#promoStatLive').textContent=states.filter(x=>x==='live').length;$('#promoStatScheduled').textContent=states.filter(x=>x==='scheduled').length;$('#promoStatInactive').textContent=states.filter(x=>x==='inactive').length;$('#promoStatCategories').textContent=new Set(promoCache.map(p=>p.category).filter(Boolean)).size}
    function filteredPromos(){const q=financeText($('#promoSearch').value),cat=$('#promoFilterCategory').value,state=$('#promoFilterState').value;return promoCache.filter(p=>(!q||[p.title,p.summary,p.badge,p.category].some(v=>financeText(v).includes(q)))&&(!cat||String(p.category||'')===cat)&&(!state||promoRuntimeState(p)===state))}
    function promoThumb(p){const url=String(p.imageUrl||'').trim();return url?`<div class="promo-thumb"><img alt="" loading="lazy" src="${escapeHtml(url)}"/></div>`:`<div class="promo-thumb">PROMO</div>`}
    function renderPromos(){updatePromoStats();const rows=filteredPromos(),root=$('#promoList');$('#promoStatus').textContent=`${rows.length} dari ${promoCache.length} promotion`;root.innerHTML=rows.length?rows.map(p=>{const state=promoRuntimeState(p);return `<div class="promo-card">${promoThumb(p)}<div class="promo-card-main"><div class="promo-card-top"><h4>${escapeHtml(p.title||'Promotion')}</h4>${promoStateChip(state)}</div><div class="promo-card-summary">${escapeHtml(p.summary||'Tanpa ringkasan')}</div><div class="promo-card-meta"><span class="chip">${escapeHtml(String(p.category||'general').toUpperCase())}</span><span class="chip">REV ${Number(p.revision||0)}</span><span class="chip">ORDER ${Number(p.sortOrder||0)}</span></div><div class="promo-card-actions"><button class="btn secondary sm" data-promo-edit="${escapeHtml(p.id)}" type="button">Edit</button><button class="btn danger sm" data-promo-delete="${escapeHtml(p.id)}" type="button">Delete</button></div></div></div>`}).join(''):`<div class="dashboard-empty">Tidak ada promotion yang cocok.</div>`}
    function updatePromoPreview(){const title=$('#promoTitle').value.trim()||'Promotion title',badge=$('#promoBadge').value.trim()||'BADGE',summary=$('#promoSummary').value.trim()||'Promotion summary will appear here.',category=$('#promoCategory').value||'general',active=$('#promoActive').value==='true',order=Number($('#promoSortOrder').value||100),url=$('#promoImageUrl').value.trim();$('#promoPreviewTitle').textContent=title;$('#promoPreviewBadge').textContent=badge.toUpperCase();$('#promoPreviewSummary').textContent=summary;$('#promoPreviewCategory').textContent=category.toUpperCase();$('#promoPreviewState').textContent=active?'ACTIVE':'INACTIVE';$('#promoPreviewState').className='chip '+(active?'green':'');$('#promoPreviewOrder').textContent='ORDER '+order;$('#promoPreviewCover').innerHTML=url?`<img alt="" src="${escapeHtml(url)}"/>`:'PROMO PREVIEW';$('#promoRevisionLabel').textContent='REVISION '+Number($('#promoRevision').value||0)}
    function setPromoPane(name){$$('.promo-editor-tab').forEach(b=>b.classList.toggle('active',b.dataset.promoPane===name));$$('[data-promo-pane-content]').forEach(p=>p.classList.toggle('active',p.dataset.promoPaneContent===name))}
    function resetPromo(){const f=$('#promoForm');f.reset();$('#promoId').value='';$('#promoRevision').value='0';$('#promoSortOrder').value='100';$('#promoCtaLabel').value='Lanjutkan';$('#promoCtaRoute').value='route-bonus';$('#promoActive').value='true';$('#promoFormTitle').textContent='New Promotion';$('#promoEditorState').textContent='DRAFT EDITOR';setPromoPane('basic');updatePromoPreview()}
    async function loadPromotions(){try{const d=await api('promotions');promoCache=Array.isArray(d.promotions)?d.promotions:[];renderPromos()}catch(err){promoCache=[];renderPromos();$('#promoStatus').textContent=err.status===404?'Endpoint promotions belum tersedia.':'Gagal memuat promotions.'}}
    function editPromo(id){const p=promoCache.find(x=>String(x.id)===String(id));if(!p)return;$('#promoId').value=p.id||'';$('#promoRevision').value=Number(p.revision||0);$('#promoTitle').value=p.title||'';$('#promoCategory').value=p.category||'general';$('#promoBadge').value=p.badge||'';$('#promoActive').value=String(p.active!==false);$('#promoSummary').value=p.summary||'';$('#promoImageUrl').value=p.imageUrl||'';$('#promoStartAt').value=localValue(p.startAt);$('#promoEndAt').value=localValue(p.endAt);$('#promoSortOrder').value=Number(p.sortOrder||100);$('#promoCtaLabel').value=p.ctaLabel||'Lanjutkan';$('#promoCtaRoute').value=p.ctaRoute||'route-bonus';$('#promoDetailIntro').value=p.detailIntro||'';const ss=Array.isArray(p.sections)?p.sections:[],body=t=>ss.find(x=>String(x.title||'').toLowerCase()===t.toLowerCase())?.body||'';$('#promoMechanism').value=body('Mekanisme');$('#promoTerms').value=body('Syarat & Ketentuan');$('#promoNote').value=body('Keterangan');$('#promoFormTitle').textContent='Edit Promotion';$('#promoEditorState').textContent='EDITING '+String(p.id||'').slice(0,10).toUpperCase();setPromoPane('basic');updatePromoPreview()}
    $('#promoForm').addEventListener('submit',async e=>{e.preventDefault();busy(true);$('#promoSubmitBtn').disabled=true;try{await api('promotions',{method:'POST',body:{action:'upsert',promotion:promoPayload(),expectedRevision:Number($('#promoRevision').value||0)}});toast('Promotion berhasil disimpan.','ok');resetPromo();await loadPromotions()}catch(err){toast(err.message==='promotion_revision_conflict'?'Promotion berubah di server. Refresh lalu edit ulang.':'Gagal menyimpan promotion: '+err.message,'error')}finally{$('#promoSubmitBtn').disabled=false;busy(false)}});
    $('#promoList').addEventListener('click',async e=>{const edit=e.target.closest('[data-promo-edit]');if(edit){editPromo(edit.dataset.promoEdit);return}const del=e.target.closest('[data-promo-delete]');if(!del)return;const current=promoCache.find(x=>String(x.id)===String(del.dataset.promoDelete));if(!current||!confirm('Delete promotion ini?'))return;busy(true);try{await api('promotions',{method:'POST',body:{action:'delete',id:del.dataset.promoDelete,expectedRevision:Number(current.revision||0)}});toast('Promotion dihapus.','ok');if($('#promoId').value===current.id)resetPromo();await loadPromotions()}catch(err){toast(err.message==='promotion_revision_conflict'?'Promotion berubah di server. Refresh dahulu.':'Gagal menghapus promotion: '+err.message,'error')}finally{busy(false)}});
    $$('.promo-editor-tab').forEach(b=>b.addEventListener('click',()=>setPromoPane(b.dataset.promoPane)));
    ['promoTitle','promoBadge','promoSummary','promoImageUrl','promoSortOrder'].forEach(id=>$('#'+id).addEventListener('input',updatePromoPreview));$('#promoCategory').addEventListener('change',updatePromoPreview);$('#promoActive').addEventListener('change',updatePromoPreview);
    $('#promoSearch').addEventListener('input',renderPromos);$('#promoFilterCategory').addEventListener('change',renderPromos);$('#promoFilterState').addEventListener('change',renderPromos);
    $('#promoRefreshBtn').addEventListener('click',loadPromotions);$('#promoNewBtn').addEventListener('click',()=>{resetPromo();$('#promoTitle').focus()});$('#promoResetBtn').addEventListener('click',resetPromo);
    resetPromo();

    /* PAYMENT */
    let gatewayCache=[];
    function openGatewayModal(){$('#modalBackdrop').classList.add('show');$('#gatewayModal').classList.add('show')}
    function closeGatewayModal(){$('#modalBackdrop').classList.remove('show');$('#gatewayModal').classList.remove('show');$('#gatewaySecret').value='';$('#gatewayCallbackSecret').value=''}
    function resetGatewayForm(){
      $('#gatewayForm').reset();$('#gatewayId').value='';$('#gatewayRevision').value='0';$('#gatewayKvList').innerHTML='';$('#gatewayBaseUrl').value='';
      $('#gatewayModal').querySelector('.modal-head h3').textContent='Add Payment Connection';
    }
    $('#newGatewayBtn').addEventListener('click',()=>{resetGatewayForm();openGatewayModal()});
    $('#gatewayClose').addEventListener('click',closeGatewayModal);$('#gatewayCancel').addEventListener('click',closeGatewayModal);$('#modalBackdrop').addEventListener('click',closeGatewayModal);
    function addGatewayField(key='',value='',secret=false,label='',kind='text'){
      const row=document.createElement('div');row.className='kv-row';row.dataset.kind=kind;row.dataset.label=label||key;
      row.innerHTML=`<input class="kv-key" placeholder="Field name" value="${escapeHtml(key)}"/><input class="kv-value" ${secret||kind==='secret'?'type="password"':''} placeholder="Value" value="${escapeHtml(value)}"/><button class="btn danger sm kv-remove" type="button">Hapus</button>`;
      row.querySelector('.kv-remove').addEventListener('click',()=>row.remove());$('#gatewayKvList').appendChild(row)
    }
    $('#addGatewayField').addEventListener('click',()=>addGatewayField());
    resetGatewayForm();
    function paymentStatusView(g){return g.operational===true?'operational':String(g.status||'adapter_unavailable')}
    function renderPaymentAdapters(d){
      const adapters=Array.isArray(d.supportedProviders)?d.supportedProviders:[];
      $('#paymentAdapterList').innerHTML=adapters.length?adapters.map(a=>`<div class="adapter-card"><div class="adapter-card-top"><strong>${escapeHtml(a.label||a.id)}</strong>${a.available?'<span class="mini-state ok">APPROVED</span>':'<span class="mini-state warn">GATED</span>'}</div><p>${a.available?'Production adapter registered.':'Production adapter belum approved.'}</p></div>`).join(''):`<div class="adapter-card"><div class="adapter-card-top"><strong>No approved payment adapters</strong><span class="mini-state warn">PENDING</span></div><p>Encrypted vault siap, tetapi transaksi real-money tetap fail-closed sampai adapter provider lolos QA.</p></div>`;
    }
    function renderPaymentConnections(){
      const operational=gatewayCache.filter(g=>g.operational===true).length,gated=gatewayCache.length-operational;
      $('#paymentStatConnections').textContent=gatewayCache.length;$('#paymentStatOperational').textContent=operational;$('#paymentStatGated').textContent=gated;
      $('#gatewayList').innerHTML=gatewayCache.length?gatewayCache.map(g=>{const fields=Array.isArray(g.credentialFields)?g.credentialFields.length:0,missing=Array.isArray(g.missingCredentials)?g.missingCredentials.length:0;return `<div class="payment-connection"><div class="payment-connection-head"><span class="payment-connection-logo">PG</span><span class="payment-connection-copy"><strong>${escapeHtml(g.label||g.provider||'Payment Gateway')}</strong><span>${escapeHtml(g.provider||'')} • ${escapeHtml(g.mode||'production')}</span></span>${stateChip(paymentStatusView(g))}</div><div class="payment-connection-meta"><div class="payment-meta"><span>Revision</span><strong>${Number(g.revision||0)}</strong></div><div class="payment-meta"><span>Credential Fields</span><strong>${fields}</strong></div><div class="payment-meta"><span>Missing Required</span><strong>${missing}</strong></div></div><div class="payment-connection-actions"><button class="btn secondary sm" data-gateway-edit="${escapeHtml(g.id)}" type="button">Edit Configuration</button></div></div>`}).join(''):`<div class="dashboard-empty">Belum ada payment connection.</div>`;
    }
    function editGateway(id){
      const g=gatewayCache.find(x=>String(x.id)===String(id));if(!g)return;
      resetGatewayForm();$('#gatewayId').value=g.id||'';$('#gatewayRevision').value=Number(g.revision||0);$('#gatewayName').value=g.label||'';$('#gatewayProvider').value=g.provider||'';$('#gatewayEnvironment').value=g.mode||'production';
      $('#gatewayModal').querySelector('.modal-head h3').textContent='Edit Payment Connection';
      const schema=Array.isArray(g.credentialSchema)?g.credentialSchema:[];$('#gatewayKvList').innerHTML='';schema.filter(f=>!['merchantId','apiKey','webhookSecret','apiBaseUrl'].includes(f.id)).forEach(f=>addGatewayField(f.id,'',f.kind==='secret',f.label,f.kind));openGatewayModal();
    }
    async function loadPayment(){
      try{const d=await api('payment');gatewayCache=Array.isArray(d.connections)?d.connections:[];$('#paymentStatVault').textContent=d.vaultConfigured?'READY':'NOT READY';$('#paymentState').textContent=d.vaultConfigured?'VAULT READY':'VAULT CHECK';renderPaymentConnections();renderPaymentAdapters(d)}
      catch(err){gatewayCache=[];$('#paymentStatConnections').textContent='—';$('#paymentStatOperational').textContent='—';$('#paymentStatGated').textContent='—';$('#paymentStatVault').textContent='ERROR';$('#gatewayList').innerHTML=`<div class="dashboard-empty">${escapeHtml(err.message||'Payment configuration unavailable.')}</div>`;if(err.status!==404)toast('Payment config gagal dimuat: '+err.message,'error')}
    }
    $('#paymentRefreshBtn').addEventListener('click',loadPayment);
    $('#gatewayList').addEventListener('click',e=>{const b=e.target.closest('[data-gateway-edit]');if(b)editGateway(b.dataset.gatewayEdit)});
    $('#gatewayForm').addEventListener('submit',async e=>{
      e.preventDefault();
      const credentials={},schema=[{id:'merchantId',label:'Merchant ID',kind:'text'},{id:'apiKey',label:'API / Private Key',kind:'secret'},{id:'webhookSecret',label:'Webhook / Callback Secret',kind:'secret'},{id:'apiBaseUrl',label:'API Base URL',kind:'url'}];
      const merchant=$('#gatewayMerchant').value.trim(),apiKey=$('#gatewaySecret').value,webhook=$('#gatewayCallbackSecret').value,baseUrl=$('#gatewayBaseUrl').value.trim();
      if(merchant)credentials.merchantId=merchant;if(apiKey)credentials.apiKey=apiKey;if(webhook)credentials.webhookSecret=webhook;if(baseUrl)credentials.apiBaseUrl=baseUrl;
      $$('#gatewayKvList .kv-row').forEach(r=>{const id=r.querySelector('.kv-key').value.trim(),value=r.querySelector('.kv-value').value;if(!id)return;const kind=r.dataset.kind||'text',label=r.dataset.label||id;if(!schema.some(f=>f.id===id))schema.push({id,label,kind});if(value.trim())credentials[id]=value});
      const id=$('#gatewayId').value.trim(),payload={...(id?{id}:{}),label:$('#gatewayName').value.trim(),provider:$('#gatewayProvider').value.trim().toLowerCase(),mode:$('#gatewayEnvironment').value,expectedRevision:Number($('#gatewayRevision').value||0),credentials,credentialSchema:schema};
      busy(true);try{await api('payment',{method:'POST',body:payload});toast('Payment connection tersimpan di encrypted vault.','ok');resetGatewayForm();closeGatewayModal();await loadPayment()}catch(err){const msg=err.message==='recent_login_required'?'Login admin harus masih baru. Logout lalu login kembali sebelum mengubah credential.':err.message;toast('Gagal menyimpan gateway: '+msg,'error')}finally{$('#gatewaySecret').value='';$('#gatewayCallbackSecret').value='';busy(false)}
    });

    /* SETTINGS */
    function updateWebsitePreview(){
      $('#sitePreviewName').textContent=$('#siteName').value.trim()||'BrandalBet';
      $('#sitePreviewSupport').textContent=$('#supportLabel').value.trim()||'Support';
      $('#sitePreviewAnnouncement').textContent=$('#announcement').value.trim()||'Announcement preview.';
      $('#sitePreviewSeoTitle').textContent=$('#seoTitle').value.trim()||'SEO title';
      $('#sitePreviewSeoDescription').textContent=$('#seoDescription').value.trim()||'SEO description preview.';
      const banner=$('#banner1').value.trim();
      $('#sitePreviewBanner').innerHTML=banner?`<img alt="" src="${escapeHtml(banner)}"/>`:'BANNER PREVIEW';
      $('#websiteAccessLabel').textContent=['admin','superadmin'].includes(currentRole)?'EDIT ACCESS':'READ ONLY';
    }
    $$('.website-tab').forEach(b=>b.addEventListener('click',()=>{$$('.website-tab').forEach(x=>x.classList.toggle('active',x===b));$$('.website-pane').forEach(x=>x.classList.toggle('active',x.dataset.pane===b.dataset.pane))}));
    ['siteName','supportLabel','announcement','banner1','seoTitle','seoDescription'].forEach(id=>$('#'+id).addEventListener('input',updateWebsitePreview));
    async function loadWebsite(){
      try{
        const d=await api('website'),s=d.settings||d;
        $('#siteName').value=s.siteName||'BrandalBet';$('#supportLabel').value=s.supportLabel||'';$('#announcement').value=s.announcement||'';$('#banner1').value=s.banner1||'';$('#banner2').value=s.banner2||'';$('#banner3').value=s.banner3||'';$('#loadingEnabled').value=String(s.loadingEnabled!==false);$('#loadingDuration').value=Number(s.loadingDuration||900);$('#loadingLogo').value=s.loadingLogo||'';$('#seoTitle').value=s.seoTitle||'';$('#seoDescription').value=s.seoDescription||'';$('#seoCover').value=s.seoCover||'';
        updateWebsitePreview();toast('Website settings loaded.','ok')
      }catch(err){toast(err.status===404?'Website settings endpoint belum tersedia.':err.message,'error')}
    }
    $('#websiteRefreshBtn').addEventListener('click',loadWebsite);
    function settingsPayload(section){
      const map={
        general:{siteName:$('#siteName').value.trim(),supportLabel:$('#supportLabel').value.trim(),announcement:$('#announcement').value.trim()},
        banner:{banner1:$('#banner1').value.trim(),banner2:$('#banner2').value.trim(),banner3:$('#banner3').value.trim()},
        loading:{loadingEnabled:$('#loadingEnabled').value==='true',loadingDuration:Number($('#loadingDuration').value||900),loadingLogo:$('#loadingLogo').value.trim()},
        seo:{seoTitle:$('#seoTitle').value.trim(),seoDescription:$('#seoDescription').value.trim(),seoCover:$('#seoCover').value.trim()}
      };
      return map[section]||{}
    }
    $$('[data-save-setting]').forEach(b=>b.addEventListener('click',async()=>{
      busy(true);try{
        await api('website',{method:'POST',body:{action:'update',section:b.dataset.saveSetting,settings:settingsPayload(b.dataset.saveSetting)}});
        toast('Website settings berhasil disimpan.','ok');await loadWebsite()
      }catch(err){toast(err.status===404?'Website settings endpoint belum tersedia.':err.message,'error')}
      finally{busy(false)}
    }));
    updateWebsitePreview();

    /* SECURITY CENTER */
    function renderSecurityCenter(){
      if(!$('#securityPermissionList'))return;
      $('#securityBackendState').textContent=currentUser?'VERIFIED':'—';
      $('#securityBootstrapState').textContent=readinessCache.bootstrapEnabled===true?'ENABLED':'DISABLED';
      const groups=[
        ['Master Control','master'],['Dashboard','dashboard'],['Members','members'],['Finance','finance'],['Game Operations','provider'],
        ['Promotions','promotions'],['Rewards / Referral / Cashback','rewards'],['Payment Gateway','payment'],['Reports','reports'],['Website Settings','website'],['Audit Log','audit']
      ];
      $('#securityPermissionList').innerHTML=groups.map(([label,screen])=>`<div class="permission-row"><span><strong>${escapeHtml(label)}</strong><span>${canOpen(screen)?'Visible for current role':'Not available for current role'}</span></span>${canOpen(screen)?'<span class="mini-state ok">ALLOWED</span>':'<span class="mini-state warn">DENIED</span>'}</div>`).join('');
      const config=Array.isArray(readinessCache.configuration)?readinessCache.configuration:[];
      $('#securityConfigList').innerHTML=config.length?config.map(c=>`<div class="config-row"><span><strong>${escapeHtml(c.name)}</strong><span>Environment configuration</span></span>${c.present?'<span class="mini-state ok">PRESENT</span>':'<span class="mini-state warn">MISSING</span>'}</div>`).join(''):`<div class="dashboard-empty">Readiness belum dimuat.</div>`;
    }
    $('#securityRefreshBtn').addEventListener('click',async()=>{await loadReadiness(currentRole);renderSecurityCenter();toast('Security state diperbarui.','ok')});

    /* AUDIT CENTER */
    function auditOutcomeGroup(r){
      const s=String(r.result||r.status||'recorded').toLowerCase();
      return ['denied','error','failed','rejected'].some(x=>s.includes(x))?'error':'success'
    }
    function filteredAudit(){
      const q=financeText($('#auditSearch').value),group=$('#auditResult').value;
      return auditCache.filter(r=>(!q||[r.actor,r.action,r.resource,r.requestId].some(v=>financeText(v).includes(q)))&&(!group||auditOutcomeGroup(r)===group))
    }
    function renderAudit(){
      const rows=filteredAudit(),errors=rows.filter(r=>auditOutcomeGroup(r)==='error').length,success=rows.length-errors;
      $('#auditStatLoaded').textContent=rows.length;$('#auditStatSuccess').textContent=success;$('#auditStatError').textContent=errors;$('#auditStatActions').textContent=new Set(rows.map(r=>r.action).filter(Boolean)).size;
      $('#auditResultText').textContent=`${rows.length} audit event ditampilkan • latest 200`;
      $('#auditTable').innerHTML=rows.length?rows.map(r=>`<tr><td>${fmtDate(r.createdAt||r.time)}</td><td>${escapeHtml(r.actor||r.email||'—')}</td><td>${escapeHtml(r.action||'—')}</td><td>${escapeHtml(r.resource||'—')}</td><td>${stateChip(r.result||r.status)}</td><td>${escapeHtml(r.requestId||'—')}</td><td><button class="detail-btn" data-detail-type="Audit" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></td></tr>`).join(''):`<tr class="empty-row"><td colspan="7">Tidak ada audit event.</td></tr>`;
      $('#auditMobileList').innerHTML=rows.length?rows.map(r=>`<div class="audit-mobile-card"><div class="audit-mobile-head"><strong>${escapeHtml(r.action||'Audit event')}</strong>${stateChip(r.result||r.status)}</div><div class="audit-mobile-sub">${escapeHtml(r.actor||'—')} • ${fmtDate(r.createdAt||r.time)}</div><div class="audit-mobile-grid"><div class="audit-mobile-kv"><span>Resource</span><strong>${escapeHtml(r.resource||'—')}</strong></div><div class="audit-mobile-kv"><span>Request ID</span><strong>${escapeHtml(r.requestId||'—')}</strong></div></div><div class="audit-mobile-actions"><button class="detail-btn" data-detail-type="Audit" data-detail="${encodeURIComponent(JSON.stringify(r))}" type="button">Detail</button></div></div>`).join(''):`<div class="dashboard-empty">Tidak ada audit event.</div>`;
    }
    async function loadAudit(){
      try{const d=await api('audit',{query:{limit:200}});auditCache=Array.isArray(d.items)?d.items:[];renderAudit()}
      catch(err){auditCache=[];renderAudit();toast('Audit gagal dimuat: '+err.message,'error')}
    }
    $('#auditRefreshBtn').addEventListener('click',loadAudit);
    $('#auditApplyBtn').addEventListener('click',renderAudit);
    $('#auditResult').addEventListener('change',renderAudit);
    $('#auditSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();renderAudit()}});

    /* REPORT EXPORT */
    function reportStatusId(type){return type==='finance'?'reportFinanceStatus':type==='game'?'reportGameStatus':'reportMemberStatus'}
    $$('[data-export]').forEach(b=>b.addEventListener('click',async()=>{
      const type=b.dataset.export,status=$('#'+reportStatusId(type));
      busy(true);b.disabled=true;status.textContent='GENERATING';
      try{
        const d=await api('reports',{method:'POST',body:{action:'export',type}});
        if(d.contentBase64&&d.filename){
          const bytes=Uint8Array.from(atob(d.contentBase64),c=>c.charCodeAt(0));
          const url=URL.createObjectURL(new Blob([bytes],{type:d.mimeType||'text/csv'}));
          const a=document.createElement('a');a.href=url;a.download=d.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
          const stamp=new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date());
          reportSession.push({type,stamp,filename:d.filename});$('#reportLastExport').textContent=`${type.toUpperCase()} • ${stamp}`;
          status.textContent='DONE';toast('Report berhasil dibuat.','ok')
        }else{status.textContent='NO FILE';toast('Report tidak menghasilkan file.','error')}
      }catch(err){status.textContent='ERROR';toast(err.status===404?'Report endpoint belum tersedia.':err.message,'error')}
      finally{b.disabled=false;busy(false)}
    }));

    window.addEventListener('hashchange',()=>{if(currentUser)openScreen((location.hash||'#dashboard').slice(1))});
